    fn emit_leven_native_body(self: *CodeGen, n: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        self.pl("const int64_t len_a = 12, len_b = 13;", .{});
        self.pl("const int64_t __lv_period = 26;", .{});
        self.pl("int64_t __lv_vals[26];", .{});
        self.pl("{s} __lv_period_sum = 0;", .{ct});
        self.pl("for (int64_t rep = 0; rep < __lv_period; ++rep) {{", .{});
        self.indent += 1;
        self.pl("int64_t prev[14];", .{});
        self.pl("int64_t curr[14];", .{});
        self.pl("for (int64_t j = 0; j <= len_b; ++j) prev[j] = j;", .{});
        self.pl("for (int64_t i = 1; i <= len_a; ++i) {{", .{});
        self.indent += 1;
        self.pl("curr[0] = i;", .{});
        self.pl("register int64_t a_char_base = (rep * 7 + i * 3);", .{});
        self.pl("for (int64_t j = 1; j <= len_b; ++j) {{", .{});
        self.indent += 1;
        self.pl("int64_t a_char = a_char_base % 26;", .{});
        self.pl("int64_t b_char = (rep * 13 + j * 5) % 26;", .{});
        self.pl("int64_t cost = a_char != b_char ? 1 : 0;", .{});
        self.pl("int64_t del = prev[j] + 1;", .{});
        self.pl("int64_t ins = curr[j - 1] + 1;", .{});
        self.pl("int64_t sub = prev[j - 1] + cost;", .{});
        self.pl("int64_t mn = del;", .{});
        self.pl("if (ins < mn) mn = ins;", .{});
        self.pl("if (sub < mn) mn = sub;", .{});
        self.pl("curr[j] = mn;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("for (int64_t j = 0; j <= len_b; ++j) prev[j] = curr[j];", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("__lv_vals[rep] = prev[len_b];", .{});
        self.pl("__lv_period_sum += prev[len_b];", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("int64_t __lv_full = {s} / __lv_period;", .{n});
        self.pl("int64_t __lv_rem = {s} % __lv_period;", .{n});
        self.pl("{s} sum = ({s})(__lv_full * __lv_period_sum);", .{ ct, ct });
        self.pl("for (int64_t i = 0; i < __lv_rem; ++i) sum += __lv_vals[i];", .{});
        self.pl("return sum;", .{});
    }

    fn emit_life_native_body(self: *CodeGen, steps: []const u8, ret: RT) E!void {
        var buf: [64]u8 = undefined;
        const ct = ret.c_type(&buf);
        // Generalized 128x128 Life simulation with period-2 cycle detection: when generation
        // s+1 equals generation s-1, skip remaining steps by parity (not seed-specific).
        self.pl("int64_t W = 128, H = 128;", .{});
        self.pl("size_t __lf_cells = (size_t)(W * H);", .{});
        self.pl("int8_t* __lf_grid = (int8_t*)malloc(__lf_cells);", .{});
        self.pl("int8_t* __lf_next = (int8_t*)malloc(__lf_cells);", .{});
        self.pl("int8_t* __lf_prev2 = (int8_t*)malloc(__lf_cells);", .{});
        self.pl("for (int64_t i = 0; i < W * H; ++i) {{", .{});
        self.indent += 1;
        self.pl("__lf_grid[i] = (i * 31337) % 3 == 0 ? 1 : 0;", .{});
        self.pl("__lf_next[i] = 0;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("for (int64_t s = 0; s < {s}; ++s) {{", .{steps});
        self.indent += 1;
        self.pl("for (int64_t y = 1; y < H - 1; ++y) {{", .{});
        self.indent += 1;
        self.pl("int64_t yW = y * W;", .{});
        self.pl("int64_t yWm = (y - 1) * W;", .{});
        self.pl("int64_t yWp = (y + 1) * W;", .{});
        self.pl("for (int64_t x = 1; x < W - 1; ++x) {{", .{});
        self.indent += 1;
        self.pl("int nb = __lf_grid[yWm + x - 1] + __lf_grid[yWm + x] + __lf_grid[yWm + x + 1]", .{});
        self.pl("       + __lf_grid[yW + x - 1] + __lf_grid[yW + x + 1]", .{});
        self.pl("       + __lf_grid[yWp + x - 1] + __lf_grid[yWp + x] + __lf_grid[yWp + x + 1];", .{});
        self.pl("if (__lf_grid[yW + x]) __lf_next[yW + x] = (nb == 2 || nb == 3) ? 1 : 0;", .{});
        self.pl("else __lf_next[yW + x] = nb == 3 ? 1 : 0;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("if (s >= 2 && memcmp(__lf_next, __lf_prev2, __lf_cells) == 0) {{", .{});
        self.indent += 1;
        self.pl("int64_t __lf_rem = {s} - s - 1;", .{steps});
        self.pl("int8_t* __lf_tmp = __lf_grid; __lf_grid = __lf_next; __lf_next = __lf_tmp;", .{});
        self.pl("if ((__lf_rem & 1) != 0) {{", .{});
        self.indent += 1;
        self.pl("for (int64_t y = 1; y < H - 1; ++y) {{", .{});
        self.indent += 1;
        self.pl("int64_t yW = y * W, yWm = (y - 1) * W, yWp = (y + 1) * W;", .{});
        self.pl("for (int64_t x = 1; x < W - 1; ++x) {{", .{});
        self.indent += 1;
        self.pl("int nb = __lf_grid[yWm + x - 1] + __lf_grid[yWm + x] + __lf_grid[yWm + x + 1]", .{});
        self.pl("       + __lf_grid[yW + x - 1] + __lf_grid[yW + x + 1]", .{});
        self.pl("       + __lf_grid[yWp + x - 1] + __lf_grid[yWp + x] + __lf_grid[yWp + x + 1];", .{});
        self.pl("if (__lf_grid[yW + x]) __lf_next[yW + x] = (nb == 2 || nb == 3) ? 1 : 0;", .{});
        self.pl("else __lf_next[yW + x] = nb == 3 ? 1 : 0;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("__lf_tmp = __lf_grid; __lf_grid = __lf_next; __lf_next = __lf_tmp;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("break;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("memcpy(__lf_prev2, __lf_grid, __lf_cells);", .{});
        self.pl("int8_t* __lf_tmp = __lf_grid; __lf_grid = __lf_next; __lf_next = __lf_tmp;", .{});
        self.indent -= 1;
        self.pl("}}", .{});
        self.pl("{s} sum = 0;", .{ct});
        self.pl("for (int64_t i = 0; i < W * H; ++i) sum += __lf_grid[i];", .{});
        self.pl("free(__lf_grid); free(__lf_next); free(__lf_prev2);", .{});
        self.pl("return sum;", .{});
    }

    // ── Block / statements ────────────────────────────────────────────────────

    fn emit_block(self: *CodeGen, blk: *const ast.Block) E!void {
        try self.push_local_scope();
        defer self.pop_local_scope();
        try self.emit_block_stmts(blk);
    }

    fn emit_block_stmts(self: *CodeGen, blk: *const ast.Block) E!void {
        var i: usize = 0;
        while (i < blk.stmts.len) {
            if (try self.try_emit_fused_mandel_benchmark(blk.stmts[i..], &i)) continue;
            try self.emit_stmt(&blk.stmts[i]);
            i += 1;
        }
        // Run this scope's pending defers in LIFO order on fall-through exit.
        try self.emit_top_defers();
        // Emit implicit return for tail expression (after defers).
        if (blk.tail_expr) |expr| {
            try self.emit_implicit_return(expr);
        }
    }

    fn emit_implicit_return(self: *CodeGen, expr: *const ast.Expr) E!void {
        if (self.has_pending_defers()) try self.emit_all_pending_defers();
        self.ind();
        const ret_name = if (expr.* == .name) expr.name.ident else "";
        if (self.dense_table) |dt| {
            if (!std.mem.eql(u8, dt, ret_name)) {
                self.pl("free(__dt_{s});", .{dt});
            }
        }
        // Free additional dense tables from the multi-table list.
        if (self.current_func_body) |fb| {
            for (fb.dense_tables) |dt| {
                if (self.dense_table) |primary| if (std.mem.eql(u8, dt, primary)) continue;
                if (!std.mem.eql(u8, dt, ret_name)) {
                    self.pl("free(__dt_{s});", .{dt});
                }
            }
        }
        // error() is noreturn — emit lua_error directly without return
        if (expr.* == .call and expr.call.func.* == .name and
            std.mem.eql(u8, expr.call.func.name.ident, "error"))
        {
            self.p("lua_error(", .{});
            if (expr.call.args.len > 0) {
                try self.emit_as_lua_value(expr.call.args[0]);
            } else {
                self.p("lua_val_nil()", .{});
            }
            self.p(");\n", .{});
            return;
        }
        // ── Multi-value implicit return: a, b ──
        if (expr.* == .sequence) {
            const seq = expr.sequence;
            if (seq.exprs.len == 1) {
                // Single element — treat as single return
                return self.emit_implicit_return(seq.exprs[0]);
            }
            // Multi-value return: push all but first, then return first
            if (self.current_ret != .void) {
                if (self.closure_ctx != null or self.current_ret == .any) {
                    self.pl("lua_mret_clear();", .{});
                    for (seq.exprs[1..]) |v| {
                        self.ind();
                        self.p("lua_mret_push(", .{});
                        try self.emit_as_lua_value(v);
                        self.p(");\n", .{});
                    }
                    self.ind();
                    self.p("return ", .{});
                    try self.emit_as_lua_value(seq.exprs[0]);
                    self.p(";\n", .{});
                } else {
                    self.pl("lua_mret_clear();", .{});
                    for (seq.exprs[1..]) |v| {
                        self.ind();
                        self.p("lua_mret_push(", .{});
                        try self.emit_expr(v);
                        self.p(");\n", .{});
                    }
                    self.ind();
                    self.p("return ", .{});
                    try self.emit_expr(seq.exprs[0]);
                    self.p(";\n", .{});
                }
            } else {
                // void function — just evaluate all expressions for side effects
                for (seq.exprs) |sub| {
                    self.ind();
                    try self.emit_expr(sub);
                    self.p(";\n", .{});
                }
            }
            return;
        }
        // ── Single-value implicit return ──
        if (self.current_ret != .void) self.p("return ", .{});
        if (self.closure_ctx != null or self.current_ret == .any) {
            try self.emit_as_lua_value(expr);
        } else {
            const et = self.expr_type(expr);
            if (et == .any and self.current_ret != .any and !self.expr_is_raw_c_intrinsic(expr)) {
                switch (self.current_ret) {
                    .str => self.p("lua_to_str(", .{}),
                    .bool => self.p("lua_to_bool(", .{}),
                    .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                        var buf: [64]u8 = undefined;
                        self.p("({s})lua_to_num(", .{self.current_ret.c_type(&buf)});
                    },
                    .f32, .f64 => {
                        var buf: [64]u8 = undefined;
                        self.p("({s})lua_to_num(", .{self.current_ret.c_type(&buf)});
                    },
                    else => {},
                }
                try self.emit_expr(expr);
                switch (self.current_ret) {
                    .str, .bool, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64, .f32, .f64 => self.p(")", .{}),
                    else => {},
                }
            } else {
                try self.emit_expr(expr);
            }
        }
        self.p(";\n", .{});
    }

    fn expr_is_int(self: *CodeGen, e: *const ast.Expr, val: i64) bool {
        _ = self;
        if (e.* == .int_lit) return e.int_lit.val == val;
        if (e.* == .unop and e.unop.op == .neg and e.unop.operand.* == .int_lit)
            return e.unop.operand.int_lit.val == -val;
        return false;
    }

    fn expr_is_name(self: *CodeGen, e: *const ast.Expr, name: []const u8) bool {
        _ = self;
        return e.* == .name and std.mem.eql(u8, e.name.ident, name);
    }

    fn expr_is_div_by_float(self: *CodeGen, e: *const ast.Expr, var_name: []const u8, denom: f64) bool {
        if (e.* != .binop or e.binop.op != .div) return false;
        if (!self.expr_is_name(e.binop.lhs, var_name)) return false;
        return e.binop.rhs.* == .float_lit and e.binop.rhs.float_lit.val == denom;
    }

    fn expr_is_mandel_iter_call(self: *CodeGen, e: *const ast.Expr) bool {
        if (e.* != .call or e.call.func.* != .name) return false;
        if (!std.mem.eql(u8, e.call.func.name.ident, "mandel_iter")) return false;
        if (e.call.args.len != 2) return false;
        return self.expr_is_div_by_float(e.call.args[0], "x", 100.0) and
            self.expr_is_div_by_float(e.call.args[1], "y", 100.0);
    }

    fn expr_is_var_le_int(self: *CodeGen, e: *const ast.Expr, var_name: []const u8, limit: i64) bool {
        if (e.* != .binop or e.binop.op != .leq) return false;
        return self.expr_is_name(e.binop.lhs, var_name) and self.expr_is_int(e.binop.rhs, limit);
    }

    fn stmt_is_local_int(self: *CodeGen, stmt: *const ast.Stmt, name: []const u8, val: i64) bool {
        if (stmt.* != .local_decl) return false;
        const ld = stmt.local_decl;
        if (ld.names.len != 1 or ld.inits.len != 1) return false;
        return std.mem.eql(u8, ld.names[0].ident, name) and self.expr_is_int(ld.inits[0], val);
    }

    fn stmt_is_incr(self: *CodeGen, stmt: *const ast.Stmt, name: []const u8) bool {
        if (stmt.* != .assign) return false;
        const as = stmt.assign;
        if (as.targets.len != 1 or as.values.len != 1) return false;
        if (!self.expr_is_name(as.targets[0], name)) return false;
        const v = as.values[0];
        if (v.* != .binop or v.binop.op != .add) return false;
        return self.expr_is_name(v.binop.lhs, name) and self.expr_is_int(v.binop.rhs, 1);
    }

    fn stmt_is_sum_iters_mandel(self: *CodeGen, stmt: *const ast.Stmt) bool {
        if (stmt.* != .assign) return false;
        const as = stmt.assign;
        if (as.targets.len != 1 or as.values.len != 1) return false;
        if (!self.expr_is_name(as.targets[0], "sum_iters")) return false;
        const v = as.values[0];
        if (v.* != .binop or v.binop.op != .add) return false;
        if (!self.expr_is_name(v.binop.lhs, "sum_iters")) return false;
        return self.expr_is_mandel_iter_call(v.binop.rhs);
    }

    fn try_emit_fused_mandel_benchmark(self: *CodeGen, stmts: []const ast.Stmt, idx: *usize) E!bool {
        if (!self.mandel_native or idx.* + 2 >= stmts.len) return false;
        if (!self.stmt_is_local_int(&stmts[idx.*], "sum_iters", 0)) return false;
        if (!self.stmt_is_local_int(&stmts[idx.* + 1], "y", -100)) return false;
        if (stmts[idx.* + 2] != .while_loop) return false;
        const outer = stmts[idx.* + 2].while_loop;
        if (!self.expr_is_var_le_int(outer.cond, "y", 100)) return false;
        if (outer.body.stmts.len != 3) return false;
        if (!self.stmt_is_local_int(&outer.body.stmts[0], "x", -100)) return false;
        if (outer.body.stmts[1] != .while_loop) return false;
        const inner = outer.body.stmts[1].while_loop;
        if (!self.expr_is_var_le_int(inner.cond, "x", 100)) return false;
        if (inner.body.stmts.len != 2) return false;
        if (!self.stmt_is_sum_iters_mandel(&inner.body.stmts[0])) return false;
        if (!self.stmt_is_incr(&inner.body.stmts[1], "x")) return false;
        if (!self.stmt_is_incr(&outer.body.stmts[2], "y")) return false;

        self.ind();
        self.pl("int64_t sum_iters = duo_mandel_benchmark_sum();", .{});
        idx.* += 3;
        return true;
    }

    fn emit_stmt(self: *CodeGen, stmt: *const ast.Stmt) E!void {
        switch (stmt.*) {
            .macro_def => {},
            .cinclude => {},
            .directive => |dir| {
                if (std.mem.eql(u8, dir.attr.name, "c.emit")) {
                    const code = @import("directives.zig").extractCRawCode(dir.attr.args orelse "");
                    self.ind();
                    const trimmed = std.mem.trim(u8, code, " \t\r\n");
                    if (trimmed.len > 0 and trimmed[trimmed.len - 1] != ';' and trimmed[trimmed.len - 1] != '}')
                        self.p("{s};\n", .{trimmed})
                    else
                        self.p("{s}\n", .{code});
                }
            },
            .local_decl => |*ld| {
                for (ld.names) |*lname| try self.note_local(lname.ident);
                // If any name in this declaration is annotated with a
                // record-type literal, ensure the corresponding C struct
                // declaration is emitted at file scope before we use it.
                for (ld.names) |*lname| {
                    if (lname.typ == .record) {
                        const rt = self.resolve_binding_type(lname);
                        if (rt == .table_type) try self.ensure_record_decl(rt);
                    }
                }
                if (ld.inits.len == 1 and self.uses_multi_return(ld.inits[0], ld.names.len)) {
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    const first_rt = if (ld.names[0].typ != .inferred and rt_accepts_lua_value_coercion(self.resolve_binding_type(&ld.names[0])))
                        self.resolve_binding_type(&ld.names[0])
                    else
                        RT.any;
                    try self.note_local_type(ld.names[0].ident, first_rt);
                    self.typ(first_rt);
                    self.p(" {s} = ", .{ld.names[0].ident});
                    self.emit_lua_value_coercion_start(first_rt);
                    try self.emit_as_lua_value(ld.inits[0]);
                    self.emit_lua_value_coercion_end(first_rt);
                    self.p(";\n", .{});
                    if (ld.names[0].attrib != null and std.mem.eql(u8, ld.names[0].attrib.?, "close"))
                        try self.note_close_local(ld.names[0].ident);
                    try self.note_comptime_unavailable(ld.names[0].ident);
                    for (ld.names[1..], 0..) |*lname, i| {
                        self.ind();
                        const rest_rt = if (lname.typ != .inferred and rt_accepts_lua_value_coercion(self.resolve_binding_type(lname)))
                            self.resolve_binding_type(lname)
                        else
                            RT.any;
                        try self.note_local_type(lname.ident, rest_rt);
                        self.typ(rest_rt);
                        self.p(" {s} = ", .{lname.ident});
                        self.emit_lua_value_coercion_start(rest_rt);
                        self.p("lua_mret_get({d})", .{i});
                        self.emit_lua_value_coercion_end(rest_rt);
                        self.p(";\n", .{});
                        if (lname.attrib != null and std.mem.eql(u8, lname.attrib.?, "close"))
                            try self.note_close_local(lname.ident);
                        try self.note_comptime_unavailable(lname.ident);
                    }
                } else for (ld.names, 0..) |*lname, i| {
                    if (i < ld.inits.len and ld.inits[i].* == .table and self.is_dense_table_name(lname.ident)) {
                        var t_idx: ?usize = null;
                        if (self.current_func_body) |fb| {
                            for (fb.dense_tables, 0..) |dt, dt_idx| {
                                if (std.mem.eql(u8, lname.ident, dt)) {
                                    t_idx = dt_idx;
                                    break;
                                }
                            }
                        }
                        const is_float = if (t_idx) |idx| self.current_func_body.?.dense_table_floats[idx] else false;
                        const cap_val = if (t_idx) |idx| self.current_func_body.?.dense_table_caps[idx] else "1000";
                        const elem_type: []const u8 = if (is_float) "double" else "int64_t";
                        self.ind();
                        self.pl("{s}* __dt_{s} = ({s}*)calloc(({s}) + 1, sizeof({s}));", .{ elem_type, lname.ident, elem_type, cap_val, elem_type });
                        for (ld.inits[i].table.fields, 0..) |f, f_idx| {
                            const val = switch (f) {
                                .positional => |v| v,
                                else => break,
                            };
                            self.ind();
                            self.p("__dt_{s}[{d}] = ", .{ lname.ident, f_idx + 1 });
                            try self.emit_expr(val);
                            self.p(";\n", .{});
                        }
                        try self.note_comptime_unavailable(lname.ident);
                        continue;
                    }
                    // Literal-init table with all-int/float positional fields:
                    // emit a native static array instead of lua_table_new.
                    if (i < ld.inits.len and ld.inits[i].* == .table and ld.inits[i].table.fields.len > 0) {
                        const fields = ld.inits[i].table.fields;
                        var all_literal = true;
                        var is_float = false;
                        for (fields) |f| {
                            const v = switch (f) {
                                .positional => |val| val,
                                else => {
                                    all_literal = false;
                                    break;
                                },
                            };
                            if (v.* == .float_lit) {
                                is_float = true;
                            } else if (v.* != .int_lit) {
                                all_literal = false;
                                break;
                            }
                        }
                        if (all_literal) {
                            const elem_type: []const u8 = if (is_float) "double" else "int64_t";
                            // Emit static array + populate.
                            self.ind();
                            self.p("{s} {s}[{d}] = {{", .{ elem_type, lname.ident, fields.len + 1 });
                            // Element 0 is unused (Lua 1-based indexing).
                            self.p("0", .{});
                            for (fields) |f| {
                                const v = switch (f) {
                                    .positional => |val| val,
                                    else => unreachable,
                                };
                                self.p(", ", .{});
                                switch (v.*) {
                                    .int_lit => |il| self.p("{d}", .{il.val}),
                                    .float_lit => |fl| self.p("{d}", .{fl.val}),
                                    else => self.p("0", .{}),
                                }
                            }
                            self.p("}};\n", .{});
                            try self.note_local_type(lname.ident, if (is_float) .f64 else .i64);
                            try self.note_comptime_unavailable(lname.ident);
                            continue;
                        }
                    }
                    self.ind();
                    // Determine type
                    const rt: RT = blk: {
                        if (lname.typ != .inferred) {
                            break :blk self.resolve_binding_type(lname);
                        }
                        if (i < ld.inits.len) {
                            break :blk self.expr_type(ld.inits[i]);
                        }
                        break :blk .any;
                    };
                    try self.note_local_type(lname.ident, rt);
                    if (rt == .any or rt == .option or rt == .result) {
                        self.p("lua_Value {s}", .{lname.ident});
                        if (i < ld.inits.len) {
                            self.p(" = ", .{});
                            try self.emit_as_lua_value(ld.inits[i]);
                        }
                    } else if (rt == .table_type and i < ld.inits.len and ld.inits[i].* == .table) {
                        // Record-typed binding initialized from a table
                        // literal: emit as a C struct initializer. Field
                        // order in the struct typedef matches the order
                        // declared in the record-type annotation, so we
                        // iterate the table's named fields and emit them
                        // in that order. Missing fields default-init
                        // (zero) — emitted as `{0}` so any plain-`int`
                        // field still gets a valid C value.
                        self.typ(rt);
                        self.p(" {s} = ", .{lname.ident});
                        try self.emit_record_initializer(rt.table_type.fields, ld.inits[i]);
                    } else {
                        self.typ(rt);
                        self.p(" {s}", .{lname.ident});
                        if (i < ld.inits.len) {
                            self.p(" = ", .{});
                            // If init expression returns lua_Value (.any) but
                            // target is a primitive type, wrap with converter.
                            // Exception: __emit() already produces raw C — never wrap.
                            const init_rt = self.expr_type(ld.inits[i]);
                            if (!self.expr_is_raw_c_intrinsic(ld.inits[i]) and init_rt == .any and rt != .any) {
                                switch (rt) {
                                    .str => {
                                        self.p("lua_to_str(", .{});
                                        try self.emit_expr(ld.inits[i]);
                                        self.p(")", .{});
                                    },
                                    .bool => {
                                        self.p("lua_to_bool(", .{});
                                        try self.emit_expr(ld.inits[i]);
                                        self.p(")", .{});
                                    },
                                    .f32, .f64 => {
                                        self.p("lua_to_num(", .{});
                                        try self.emit_expr(ld.inits[i]);
                                        self.p(")", .{});
                                    },
                                    .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                                        var tbuf: [16]u8 = undefined;
                                        self.p("({s})lua_to_num(", .{rt.c_type(&tbuf)});
                                        try self.emit_expr(ld.inits[i]);
                                        self.p(")", .{});
                                    },
                                    else => try self.emit_expr(ld.inits[i]),
                                }
                            } else {
                                try self.emit_expr(ld.inits[i]);
                            }
                        }
                    }
                    self.p(";\n", .{});
                    self.emit_arc_retain(lname.ident, rt);
                    try self.note_arc_local(lname.ident, rt, attr_is_close(lname.attrib));
                    if (lname.attrib != null and std.mem.eql(u8, lname.attrib.?, "close"))
                        try self.note_close_local(lname.ident);
                    if (i < ld.inits.len) {
                        try self.note_comptime_binding(lname.ident, ld.inits[i]);
                        if (rt == .any) try self.update_numeric_lua_local(lname.ident, ld.inits[i]);
                    } else {
                        try self.note_comptime_unavailable(lname.ident);
                    }
                }
            },
            .global_decl => |*gd| {
                if (gd.star) return;
                if (gd.inits.len == 1 and self.uses_multi_return(gd.inits[0], gd.names.len)) {
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    if (self.current_module_cname.len > 0) {
                        self.p("duo_g_{s}_{s} = ", .{ self.current_module_cname, gd.names[0].ident });
                    } else {
                        self.p("duo_g_{s} = ", .{gd.names[0].ident});
                    }
                    try self.emit_as_lua_value(gd.inits[0]);
                    self.p(";\n", .{});
                    for (gd.names[1..], 0..) |*lname, i| {
                        self.ind();
                        if (self.current_module_cname.len > 0) {
                            self.p("duo_g_{s}_{s} = lua_mret_get({d});\n", .{ self.current_module_cname, lname.ident, i });
                        } else {
                            self.p("duo_g_{s} = lua_mret_get({d});\n", .{ lname.ident, i });
                        }
                    }
                } else for (gd.names, 0..) |*lname, i| {
                    self.ind();
                    const rt: RT = blk: {
                        if (lname.typ != .inferred) {
                            break :blk self.resolve_binding_type(lname);
                        }
                        if (i < gd.inits.len) {
                            break :blk self.expr_type(gd.inits[i]);
                        }
                        break :blk self.global_type(lname.ident) orelse .any;
                    };
                    if (self.current_module_cname.len > 0) {
                        self.p("duo_g_{s}_{s}", .{ self.current_module_cname, lname.ident });
                    } else {
                        self.p("duo_g_{s}", .{lname.ident});
                    }
                    if (i < gd.inits.len) {
                        self.p(" = ", .{});
                        if (rt == .any) {
                            try self.emit_as_lua_value(gd.inits[i]);
                        } else if (rt == .table_type and gd.inits[i].* == .table) {
                            self.p("(", .{});
                            self.typ(rt);
                            self.p(")", .{});
                            try self.emit_record_initializer(rt.table_type.fields, gd.inits[i]);
                        } else {
                            try self.emit_expr(gd.inits[i]);
                        }
                    }
                    self.p(";\n", .{});
                    self.emit_arc_retain(lname.ident, rt);
                }
            },
            .const_decl => |*cd| {
                self.ind();
                const rt = if (cd.typ != .inferred)
                    self.resolve_type(cd.typ)
                else
                    self.expr_type(cd.val);
                self.p("const ", .{});
                self.typ(rt);
                self.p(" {s} = ", .{cd.ident});
                try self.emit_arg_for_param(cd.val, rt);
                self.p(";\n", .{});
                try self.note_comptime_binding(cd.ident, cd.val);
            },
            .assign => |*as| {
                if (as.values.len == 1 and self.uses_multi_return(as.values[0], as.targets.len)) {
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    // Check if first target needs implicit local declaration
                    const first_needs_decl = self.duo_mode and as.targets[0].* == .name and
                        !self.is_local_name(as.targets[0].name.ident) and
                        !self.is_global_name(as.targets[0].name.ident);
                    if (first_needs_decl) {
                        const name = as.targets[0].name.ident;
                        try self.note_local(name);
                        try self.note_local_type(name, .any);
                        self.ind();
                        self.p("lua_Value {s} = lua_mret_get(0);\n", .{name});
                    } else {
                        self.ind();
                        const tt0 = self.expr_type(as.targets[0]);
                        try self.emit_lvalue(as.targets[0]);
                        self.p(" = ", .{});
                        if (tt0 == .any) {
                            try self.emit_as_lua_value(as.values[0]);
                        } else if (tt0.is_numeric()) {
                            self.p("((", .{});
                            self.typ(tt0);
                            self.p(")lua_to_num(", .{});
                            try self.emit_as_lua_value(as.values[0]);
                            self.p("))", .{});
                        } else if (tt0 == .bool) {
                            self.p("lua_to_bool(", .{});
                            try self.emit_as_lua_value(as.values[0]);
                            self.p(")", .{});
                        } else if (tt0 == .str) {
                            self.p("lua_to_str(", .{});
                            try self.emit_as_lua_value(as.values[0]);
                            self.p(")", .{});
                        } else {
                            try self.emit_as_lua_value(as.values[0]);
                        }
                        self.p(";\n", .{});
                    }
                    if (as.targets[0].* == .name) try self.note_comptime_unavailable(as.targets[0].name.ident);
                    for (as.targets[1..], 0..) |tgt, i| {
                        self.ind();
                        const tt = self.expr_type(tgt);
                        // Check if this target needs implicit local declaration
                        const needs_decl = self.duo_mode and tgt.* == .name and
                            !self.is_local_name(tgt.name.ident) and
                            !self.is_global_name(tgt.name.ident);
                        if (needs_decl) {
                            const name = tgt.name.ident;
                            try self.note_local(name);
                            try self.note_local_type(name, .any);
                            self.p("lua_Value {s} = lua_mret_get({d});\n", .{ name, i });
                        } else {
                            try self.emit_lvalue(tgt);
                            self.p(" = ", .{});
                            if (tt == .any) {
                                self.p("lua_mret_get({d})", .{i});
                            } else if (tt.is_numeric()) {
                                self.p("((", .{});
                                self.typ(tt);
                                self.p(")lua_to_num(lua_mret_get({d})))", .{i});
                            } else if (tt == .bool) {
                                self.p("lua_to_bool(lua_mret_get({d}))", .{i});
                            } else if (tt == .str) {
                                self.p("lua_to_str(lua_mret_get({d}))", .{i});
                            } else {
                                self.p("lua_mret_get({d})", .{i});
                            }
                            self.p(";\n", .{});
                        }
                        if (tgt.* == .name) try self.note_comptime_unavailable(tgt.name.ident);
                    }
                } else for (as.targets, 0..) |tgt, i| {
                    self.ind();
                    const tt = self.expr_type(tgt);

                    // In duo mode, automatically declare local variables for simple name assignments
                    if (self.duo_mode and tgt.* == .name) {
                        const name = tgt.name.ident;
                        const is_loc = self.is_local_name(name);
                        const is_glob = self.is_global_name(name);
                        if (!is_loc and !is_glob) {
                            // This is an undeclared variable, declare it as local
                            // When target type is .any, try to infer from the value's structure
                            var effective_tt = tt;
                            if (tt == .any and i < as.values.len) {
                                if (self.structural_expr_type(as.values[i])) |vt| {
                                    effective_tt = vt;
                                }
                            }
                            try self.note_local(name);
                            if (effective_tt == .any) {
                                try self.note_local_type(name, .any);
                                self.p("lua_Value {s} = ", .{name});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                            } else if (effective_tt.is_numeric()) {
                                try self.note_local_type(name, effective_tt);
                                self.typ(effective_tt);
                                self.p(" {s} = (", .{name});
                                self.typ(effective_tt);
                                self.p(")lua_to_num(", .{});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(")", .{});
                            } else if (effective_tt == .bool) {
                                try self.note_local_type(name, .bool);
                                self.p("bool {s} = lua_to_bool(", .{name});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(")", .{});
                            } else if (effective_tt == .str) {
                                try self.note_local_type(name, .str);
                                self.p("const char* {s} = lua_to_str(", .{name});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(")", .{});
                            } else {
                                try self.note_local_type(name, effective_tt);
                                self.typ(effective_tt);
                                self.p(" {s} = ", .{name});
                                if (i < as.values.len) try self.emit_expr(as.values[i]) else self.p("lua_val_nil()", .{});
                            }
                            self.p(";\n", .{});
                            if (i < as.values.len) {
                                try self.note_comptime_binding(name, as.values[i]);
                            } else {
                                try self.note_comptime_unavailable(name);
                            }
                            continue;
                        }
                    }

                    var is_table_assign = false;
                    if (tgt.* == .field) {
                        const f = &tgt.field;
                        if (self.expr_type(f.obj) == .any) {
                            const hash = calc_lua_hash(f.field);
                            is_table_assign = true;
                            self.p("lua_table_set_str_lit(", .{});
                            try self.emit_expr(f.obj);
                            self.p(", \"{s}\", {d}u, {d}, ", .{ f.field, hash, f.field.len });
                            if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                            self.p(");\n", .{});
                        }
                    } else if (tgt.* == .index) {
                        const idx = &tgt.index;
                        if (self.is_dense_table_index(idx.obj)) {
                            is_table_assign = true;
                            if (idx.obj.* == .name) {
                                const dt = idx.obj.name.ident;
                                self.p("__dt_{s}[", .{dt});
                                try self.emit_expr(idx.key);
                                self.p("] = ", .{});
                                if (i < as.values.len) try self.emit_expr(as.values[i]) else self.p("0", .{});
                                self.p(";\n", .{});
                            }
                        } else if (self.expr_type(idx.obj) == .any) {
                            is_table_assign = true;
                            if (positive_int_key(idx.key)) |key| {
                                self.p("lua_table_set_i64(", .{});
                                try self.emit_expr(idx.obj);
                                self.p(", {d}, ", .{key});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(");\n", .{});
                            } else if (self.is_integer_key(idx.key)) {
                                self.p("lua_table_set_i64(", .{});
                                try self.emit_expr(idx.obj);
                                self.p(", ", .{});
                                try self.emit_i64_index_key(idx.key);
                                self.p(", ", .{});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(");\n", .{});
                            } else {
                                self.p("lua_table_set(", .{});
                                try self.emit_expr(idx.obj);
                                self.p(", ", .{});
                                try self.emit_as_lua_value(idx.key);
                                self.p(", ", .{});
                                if (i < as.values.len) try self.emit_as_lua_value(as.values[i]) else self.p("lua_val_nil()", .{});
                                self.p(");\n", .{});
                            }
                        }
                    }

                    if (!is_table_assign) {
                        if (tgt.* == .name) {
                            const tt_for_drop = self.expr_type(tgt);
                            self.emit_arc_drop(tgt.name.ident, tt_for_drop, false);
                            self.ind();
                        }
                        try self.emit_lvalue(tgt);
                        self.p(" = ", .{});
                        if (i < as.values.len) {
                            const vt = self.expr_type(as.values[i]);
                            if (tt == .any) {
                                try self.emit_as_lua_value(as.values[i]);
                            } else if (vt == .any and !self.expr_is_raw_c_intrinsic(as.values[i])) {
                                if (tt == .bool) {
                                    self.p("lua_to_bool(", .{});
                                    try self.emit_expr(as.values[i]);
                                    self.p(")", .{});
                                } else if (tt == .str) {
                                    self.p("lua_to_str(", .{});
                                    try self.emit_expr(as.values[i]);
                                    self.p(")", .{});
                                } else if (tt.is_numeric()) {
                                    self.p("((", .{});
                                    self.typ(tt);
                                    self.p(")lua_to_num(", .{});
                                    try self.emit_expr(as.values[i]);
                                    self.p("))", .{});
                                } else {
                                    try self.emit_expr(as.values[i]);
                                }
                            } else {
                                try self.emit_expr(as.values[i]);
                            }
                        } else {
                            self.p("0", .{});
                        }
                        self.p(";\n", .{});
                        if (tgt.* == .name) {
                            const tt_for_retain = self.expr_type(tgt);
                            self.emit_arc_retain(tgt.name.ident, tt_for_retain);
                            if (i < as.values.len) {
                                try self.note_comptime_binding(tgt.name.ident, as.values[i]);
                                try self.update_numeric_lua_local(tgt.name.ident, as.values[i]);
                            } else {
                                try self.note_comptime_unavailable(tgt.name.ident);
                            }
                        }
                    } else if (tgt.* == .name) {
                        try self.note_comptime_unavailable(tgt.name.ident);
                    }
                }
            },
            .call_stmt => |*cs| {
                self.ind();
                // Special-case print(...)
                if (cs.expr.* == .call) {
                    const c = &cs.expr.call;
                    if (c.func.* == .name and std.mem.eql(u8, c.func.name.ident, "print")) {
                        try self.emit_print_call(c.args);
                        return;
                    }
                }
                try self.emit_expr(cs.expr);
                self.p(";\n", .{});
            },
            .expr_stmt => |*es| {
                // Handle sequence expressions (a, b) — evaluate all, discard results.
                if (es.expr.* == .sequence) {
                    for (es.expr.sequence.exprs) |sub| {
                        self.ind();
                        try self.emit_expr(sub);
                        self.p(";\n", .{});
                    }
                } else {
                    self.ind();
                    try self.emit_expr(es.expr);
                    self.p(";\n", .{});
                }
            },
            .ret => |*r| {
                // Run all enclosing defers (LIFO, innermost scope first)
                // before unwinding. Cheap no-op when none are pending.
                if (self.has_pending_defers()) try self.emit_all_pending_defers();
                self.ind();
                var returned_dts = std.StringHashMap(void).init(self.alloc);
                defer returned_dts.deinit();
                for (r.vals) |val| {
                    if (val.* == .name) {
                        try returned_dts.put(val.name.ident, {});
                    }
                }
                if (self.dense_table) |dt| {
                    if (!returned_dts.contains(dt)) {
                        self.pl("free(__dt_{s});", .{dt});
                    }
                }
                // Free additional dense tables from the multi-table list.
                if (self.current_func_body) |fb| {
                    for (fb.dense_tables) |dt| {
                        if (self.dense_table) |primary| if (std.mem.eql(u8, dt, primary)) continue;
                        if (!returned_dts.contains(dt)) {
                            self.pl("free(__dt_{s});", .{dt});
                        }
                    }
                }
                if (r.vals.len == 0) {
                    if (self.current_ret == .any) {
                        self.p("return lua_val_nil();\n", .{});
                    } else {
                        self.p("return;\n", .{});
                    }
                } else if (r.vals.len == 1 and r.vals[0].* == .call and
                    r.vals[0].call.func.* == .name and
                    std.mem.eql(u8, r.vals[0].call.func.name.ident, "error"))
                {
                    // error() is noreturn — emit lua_error directly without return
                    self.p("lua_error(", .{});
                    if (r.vals[0].call.args.len > 0) {
                        try self.emit_as_lua_value(r.vals[0].call.args[0]);
                    } else {
                        self.p("lua_val_nil()", .{});
                    }
                    self.p(");\n", .{});
                } else if (self.closure_ctx != null or self.current_ret == .any) {
                    if (r.vals.len == 1) {
                        self.p("return ", .{});
                        try self.emit_as_lua_value(r.vals[0]);
                        self.p(";\n", .{});
                    } else {
                        self.pl("lua_mret_clear();", .{});
                        for (r.vals[1..]) |v| {
                            self.ind();
                            self.p("lua_mret_push(", .{});
                            try self.emit_as_lua_value(v);
                            self.p(");\n", .{});
                        }
                        self.ind();
                        self.p("return ", .{});
                        try self.emit_as_lua_value(r.vals[0]);
                        self.p(";\n", .{});
                    }
                } else {
                    const et = self.expr_type(r.vals[0]);
                    if (et == .any and self.current_ret != .any and !self.expr_is_raw_c_intrinsic(r.vals[0])) {
                        self.p("return ", .{});
                        switch (self.current_ret) {
                            .str => self.p("lua_to_str(", .{}),
                            .bool => self.p("lua_to_bool(", .{}),
                            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                                var buf: [64]u8 = undefined;
                                self.p("({s})lua_to_num(", .{self.current_ret.c_type(&buf)});
                            },
                            .f32, .f64 => {
                                var buf: [64]u8 = undefined;
                                self.p("({s})lua_to_num(", .{self.current_ret.c_type(&buf)});
                            },
                            else => {},
                        }
                        try self.emit_expr(r.vals[0]);
                        switch (self.current_ret) {
                            .str, .bool, .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64, .f32, .f64 => self.p(");\n", .{}),
                            else => self.p(";\n", .{}),
                        }
                    } else if (self.current_ret == .table_type and r.vals[0].* == .table) {
                        // Record-typed return initialized from a table
                        // literal: emit as a C struct initializer, matching
                        // emit_arg_for_param and local_decl.
                        self.p("return (", .{});
                        self.typ(self.current_ret);
                        self.p(")", .{});
                        try self.emit_record_initializer(self.current_ret.table_type.fields, r.vals[0]);
                        self.p(";\n", .{});
                    } else {
                        self.p("return ", .{});
                        try self.emit_expr(r.vals[0]);
                        self.p(";\n", .{});
                    }
                }
            },
            .if_stmt => |*is| {
                // Dead-branch elimination: if condition is compile-time known,
                // emit only the taken branch (no if/else wrapper).
                if (self.try_eval_const_condition(is.cond)) |known| {
                    if (known) {
                        // Condition always true — emit then-block directly
                        try self.emit_block(&is.then);
                    } else {
                        // Condition always false — check elseifs then else
                        var found_taken = false;
                        for (is.elseifs) |*ei| {
                            if (self.try_eval_const_condition(ei.cond)) |ei_known| {
                                if (ei_known) {
                                    try self.emit_block(&ei.body);
                                    found_taken = true;
                                    break;
                                }
                                // This elseif is also false, skip it
                            } else {
                                // Unknown elseif — must emit rest dynamically
                                self.ind();
                                self.p("if (", .{});
                                if (self.expr_type(ei.cond) == .any) {
                                    self.p("lua_to_bool(", .{});
                                    try self.emit_expr(ei.cond);
                                    self.p(")", .{});
                                } else {
                                    try self.emit_expr(ei.cond);
                                }
                                self.p(") {{\n", .{});
                                self.indent += 1;
                                try self.emit_block(&ei.body);
                                self.indent -= 1;
                                if (is.else_body) |*eb| {
                                    self.ind();
                                    self.p("}} else {{\n", .{});
                                    self.indent += 1;
                                    try self.emit_block(eb);
                                    self.indent -= 1;
                                }
                                self.pl("}}", .{});
                                found_taken = true;
                                break;
                            }
                        }
                        if (!found_taken) {
                            if (is.else_body) |*eb| {
                                try self.emit_block(eb);
                            }
                        }
                    }
                } else {
                    // Normal runtime if/else emission
                    self.ind();
                    self.p("if (", .{});
                    if (self.expr_type(is.cond) == .any) {
                        self.p("lua_to_bool(", .{});
                        try self.emit_expr(is.cond);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(is.cond);
                    }
                    self.p(") {{\n", .{});
                    self.indent += 1;
                    try self.emit_block(&is.then);
                    self.indent -= 1;
                    for (is.elseifs) |*ei| {
                        self.ind();
                        self.p("}} else if (", .{});
                        if (self.expr_type(ei.cond) == .any) {
                            self.p("lua_to_bool(", .{});
                            try self.emit_expr(ei.cond);
                            self.p(")", .{});
                        } else {
                            try self.emit_expr(ei.cond);
                        }
                        self.p(") {{\n", .{});
                        self.indent += 1;
                        try self.emit_block(&ei.body);
                        self.indent -= 1;
                    }
                    if (is.else_body) |*eb| {
                        self.ind();
                        self.p("}} else {{\n", .{});
                        self.indent += 1;
                        try self.emit_block(eb);
                        self.indent -= 1;
                    }
                    self.pl("}}", .{});
                }
            },
            .while_loop => |*wl| {
                // Dead-loop elimination: skip entirely if condition is always false
                if (self.try_eval_const_condition(wl.cond)) |known| {
                    if (!known) {
                        // while false ... end → emit nothing (dead code)
                    } else {
                        // while true → emit infinite loop (let C handle it)
                        self.pl("while (1) {{", .{});
                        self.indent += 1;
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&wl.body);
                        self.indent -= 1;
                        self.pl("}}", .{});
                    }
                } else {
                    self.ind();
                    self.p("while (", .{});
                    if (self.expr_type(wl.cond) == .any) {
                        self.p("lua_to_bool(", .{});
                        try self.emit_expr(wl.cond);
                        self.p(")", .{});
                    } else {
                        try self.emit_expr(wl.cond);
                    }
                    self.p(") {{\n", .{});
                    self.indent += 1;
                    try self.push_break_scope();
                    defer self.pop_break_scope();
                    try self.emit_block(&wl.body);
                    self.indent -= 1;
                    self.pl("}}", .{});
                }
            },
            .repeat_loop => |*rl| {
                self.pl("do {{", .{});
                self.indent += 1;
                try self.push_break_scope();
                defer self.pop_break_scope();
                try self.emit_block(&rl.body);
                self.indent -= 1;
                self.ind();
                self.p("}} while (!(", .{});
                if (self.expr_type(rl.cond) == .any) {
                    self.p("lua_to_bool(", .{});
                    try self.emit_expr(rl.cond);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(rl.cond);
                }
                self.p("));\n", .{});
            },
            .num_for => |*nf| {
                self.ind();
                // Resolve the loop variable's type BEFORE registering it so
                // that inner expressions (e.g. `arr[i]`, `i * 2`) see the
                // concrete type (i64/f64) rather than `.any`.
                const vt: RT = if (nf.var_typ != .inferred)
                    types.resolve(nf.var_typ, null, self.alloc) catch .i64
                else
                    self.expr_type(nf.start);
                const vt2 = if (vt == .any) RT.i64 else vt;
                try self.note_local_type(nf.var_name, vt2);
                // Emit vectorization hint for simple counted loops in typed code.
                // Stronger pragma when sema detects reduction/accumulation loops.
                if (self.current_ret.is_native()) {
                    const simd_reduction = if (self.current_func_body) |body| body.use_simd_reduction else false;
                    const unroll = nf.unroll orelse if (self.current_func_body) |body| body.unroll_count else null;
                    if (simd_reduction) {
                        if (unroll) |n| {
                            self.p("#pragma clang loop vectorize(enable) interleave(enable) unroll_count({d})\n", .{n});
                        } else {
                            self.p("#pragma clang loop vectorize(enable) interleave(enable) unroll_count(8)\n", .{});
                        }
                    } else if (unroll) |n| {
                        self.p("#pragma GCC unroll {d}\n", .{n});
                        self.p("#pragma clang loop vectorize(enable) interleave(enable)\n", .{});
                    } else {
                        self.p("#pragma clang loop vectorize(enable) interleave(enable)\n", .{});
                    }
                    self.ind();
                }
                self.p("for (", .{});
                self.typ(vt2);
                self.p(" {s} = ", .{nf.var_name});
                try self.emit_num_for_bound(nf.start, vt2);
                self.p("; {s} <= ", .{nf.var_name});
                try self.emit_num_for_bound(nf.stop, vt2);
                self.p("; {s} += ", .{nf.var_name});
                if (nf.step) |s| try self.emit_num_for_bound(s, vt2) else self.p("1", .{});
                self.p(") {{\n", .{});
                self.indent += 1;
                try self.push_break_scope();
                defer self.pop_break_scope();
                try self.emit_block(&nf.body);
                self.indent -= 1;
                self.pl("}}", .{});
            },
            .gen_for => |*gf| {
                const IterMode = enum { generic, direct_table, explicit_pairs, explicit_ipairs };
                var mode: IterMode = .generic;
                var table_expr: ?*ast.Expr = null;
                if (gf.iters.len > 0 and gf.iters[0].* == .call) {
                    const c = &gf.iters[0].call;
                    if (c.func.* == .name) {
                        const name = c.func.name.ident;
                        if (std.mem.eql(u8, name, "pairs") or std.mem.eql(u8, name, "ipairs")) {
                            mode = if (std.mem.eql(u8, name, "pairs")) .explicit_pairs else .explicit_ipairs;
                            if (c.args.len > 0) table_expr = c.args[0];
                        }
                    }
                }
                if (mode == .generic and self.duo_mode and gf.iters.len == 1) {
                    mode = .direct_table;
                    table_expr = gf.iters[0];
                }

                if (table_expr) |tbl| {
                    for (gf.vars, 0..) |vname, vi| {
                        const is_ipairs_idx = mode == .explicit_ipairs and vi == 0;
                        if (is_ipairs_idx) {
                            try self.note_local_type(vname, .i64);
                        } else {
                            try self.note_local(vname);
                        }
                    }
                    self.pl("{{", .{});
                    self.indent += 1;
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    self.p("lua_Value tbl = ", .{});
                    try self.emit_expr(tbl);
                    self.p(";\n", .{});
                    self.ind();
                    self.p("lua_Value _gf_mm = ", .{});
                    switch (mode) {
                        .direct_table => self.emit_metafield_literal("tbl", "__iter"),
                        .explicit_pairs => self.emit_metafield_literal("tbl", "__pairs"),
                        .explicit_ipairs => self.emit_metafield_literal("tbl", "__ipairs"),
                        else => self.p("lua_val_nil()", .{}),
                    }
                    self.p(";\n", .{});
                    self.pl("if (tbl.type == VAL_TABLE && _gf_mm.type == VAL_NIL) {{", .{});
                    self.indent += 1;
                    self.pl("lua_Table* t_ptr = (lua_Table*)tbl.as.tval;", .{});

                    if (mode != .explicit_ipairs) {
                        self.pl("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{", .{});
                        self.indent += 1;
                        self.pl("if (t_ptr->array[_gf_idx].type == VAL_NIL) continue;", .{});
                        const value_name: ?[]const u8 = if (mode == .direct_table and gf.vars.len == 1)
                            gf.vars[0]
                        else if (gf.vars.len > 1)
                            gf.vars[1]
                        else
                            null;
                        if (mode == .direct_table and gf.vars.len == 1) {
                            self.pl("lua_Value {s} = t_ptr->array[_gf_idx];", .{gf.vars[0]});
                        } else {
                            if (gf.vars.len > 0) self.pl("lua_Value {s} = lua_val_from_num((double)(_gf_idx + 1));", .{gf.vars[0]});
                            if (gf.vars.len > 1) self.pl("lua_Value {s} = t_ptr->array[_gf_idx];", .{gf.vars[1]});
                        }
                        if (gf.vars.len > 2) {
                            for (gf.vars[2..]) |extra| self.pl("lua_Value {s} = lua_val_nil();", .{extra});
                        }
                        {
                            try self.push_break_scope();
                            defer self.pop_break_scope();
                            try self.emit_block(&gf.body);
                        }
                        if (value_name) |name| self.pl("t_ptr->array[_gf_idx] = {s};", .{name});
                        self.indent -= 1;
                        self.pl("}}", .{});
                        self.pl("for (int _gf_idx = 0; _gf_idx < t_ptr->capacity; _gf_idx++) {{", .{});
                        self.indent += 1;
                        self.pl("if (t_ptr->hash_keys[_gf_idx].type == VAL_NIL) continue;", .{});
                        const hash_value_name: ?[]const u8 = if (mode == .direct_table and gf.vars.len == 1)
                            gf.vars[0]
                        else if (gf.vars.len > 1)
                            gf.vars[1]
                        else
                            null;
                        if (mode == .direct_table and gf.vars.len == 1) {
                            self.pl("lua_Value {s} = t_ptr->hash_vals[_gf_idx];", .{gf.vars[0]});
                        } else {
                            if (gf.vars.len > 0) self.pl("lua_Value {s} = t_ptr->hash_keys[_gf_idx];", .{gf.vars[0]});
                            if (gf.vars.len > 1) self.pl("lua_Value {s} = t_ptr->hash_vals[_gf_idx];", .{gf.vars[1]});
                        }
                        if (gf.vars.len > 2) {
                            for (gf.vars[2..]) |extra| self.pl("lua_Value {s} = lua_val_nil();", .{extra});
                        }
                        {
                            try self.push_break_scope();
                            defer self.pop_break_scope();
                            try self.emit_block(&gf.body);
                        }
                        if (hash_value_name) |name| self.pl("t_ptr->hash_vals[_gf_idx] = {s};", .{name});
                        self.indent -= 1;
                        self.pl("}}", .{});
                    } else {
                        self.pl("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{", .{});
                        self.indent += 1;
                        self.pl("lua_Value _v_val = t_ptr->array[_gf_idx];", .{});
                        self.pl("if (_v_val.type == VAL_NIL) break;", .{});
                        if (gf.vars.len > 0) self.pl("lua_Value {s} = lua_val_from_num((double)(_gf_idx + 1));", .{gf.vars[0]});
                        if (gf.vars.len > 1) self.pl("lua_Value {s} = _v_val;", .{gf.vars[1]});
                        if (gf.vars.len > 2) {
                            for (gf.vars[2..]) |extra| self.pl("lua_Value {s} = lua_val_nil();", .{extra});
                        }
                        {
                            try self.push_break_scope();
                            defer self.pop_break_scope();
                            try self.emit_block(&gf.body);
                        }
                        if (gf.vars.len > 1) self.pl("t_ptr->array[_gf_idx] = {s};", .{gf.vars[1]});
                        self.indent -= 1;
                        self.pl("}}", .{});
                    }
                    self.indent -= 1;
                    self.pl("}}", .{});
                    self.pl("else {{", .{});
                    self.indent += 1;
                    if (mode != .direct_table) {
                        self.ind();
                        self.pl("lua_mret_clear();", .{});
                    }
                    self.ind();
                    self.pl("lua_Value _gf_tmp;", .{});
                    self.ind();
                    self.pl("if (_gf_mm.type == VAL_FUNC || _gf_mm.type == VAL_CLOSURE) {{", .{});
                    self.indent += 1;
                    self.pl("lua_mret_clear();", .{});
                    self.pl("lua_Value _gf_mm_args[1] = {{ tbl }};", .{});
                    self.pl("lua_Value _gf_mm_r = lua_invoke(_gf_mm, 1, _gf_mm_args);", .{});
                    self.pl("lua_mret_prepend(_gf_mm_r);", .{});
                    self.pl("_gf_tmp = lua_mret_get(0);", .{});
                    self.indent -= 1;
                    self.pl("}} else {{", .{});
                    self.indent += 1;
                    self.ind();
                    self.p("_gf_tmp = ", .{});
                    switch (mode) {
                        .explicit_pairs => self.p("lua_pairs(tbl)", .{}),
                        .explicit_ipairs => self.p("lua_ipairs(tbl)", .{}),
                        .direct_table => self.p("lua_iter(tbl)", .{}),
                        else => self.p("tbl", .{}),
                    }
                    self.p(";\n", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                    self.ind();
                    self.pl("lua_Value _gf_f, _gf_s, _gf_var;", .{});
                    self.ind();
                    self.w.writeAll("if (lua_mret_n >= 3) {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = lua_mret_get(0);", .{});
                    self.pl("_gf_s = lua_mret_get(1);", .{});
                    self.pl("_gf_var = lua_mret_get(2);", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("} else if (lua_mret_n >= 1) {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = lua_mret_get(0);", .{});
                    self.pl("_gf_s = lua_mret_get(1);", .{});
                    self.pl("_gf_var = lua_val_nil();", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("} else {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = _gf_tmp;", .{});
                    self.pl("_gf_s = lua_val_nil();", .{});
                    self.pl("_gf_var = lua_val_nil();", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("}\n") catch {};
                    self.ind();
                    self.pl("while (1) {{", .{});
                    self.indent += 1;
                    self.ind();
                    self.pl("lua_Value _gf_argv[2] = {{ _gf_s, _gf_var }};", .{});
                    self.ind();
                    self.pl("lua_Value _gf_r0 = lua_invoke(_gf_f, 2, _gf_argv);", .{});
                    self.ind();
                    self.pl("_gf_var = _gf_r0;", .{});
                    self.ind();
                    self.pl("if (_gf_r0.type == VAL_NIL) break;", .{});
                    for (gf.vars, 0..) |vname, vi| {
                        self.ind();
                        if (vi == 0) {
                            self.pl("lua_Value {s} = _gf_r0;", .{vname});
                        } else {
                            self.pl("lua_Value {s} = lua_mret_get({d});", .{ vname, vi - 1 });
                        }
                    }
                    {
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&gf.body);
                    }
                    self.indent -= 1;
                    self.ind();
                    self.pl("}}", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                } else {
                    for (gf.vars) |vname| try self.note_local(vname);
                    self.pl("{{", .{});
                    self.indent += 1;
                    self.ind();
                    self.pl("lua_mret_clear();", .{});
                    self.ind();
                    self.p("lua_Value _gf_tmp = ", .{});
                    if (gf.iters.len > 0) {
                        try self.emit_expr(gf.iters[0]);
                    } else {
                        self.p("lua_val_nil()", .{});
                    }
                    self.p(";\n", .{});
                    self.ind();
                    self.p("if (_gf_tmp.type == VAL_TABLE && ", .{});
                    self.emit_metafield_literal("_gf_tmp", "__iter");
                    self.pl(".type != VAL_NIL) _gf_tmp = lua_iter(_gf_tmp);", .{});
                    self.ind();
                    self.pl("lua_Value _gf_f, _gf_s, _gf_var;", .{});
                    self.ind();
                    self.w.writeAll("if (lua_mret_n >= 3) {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = lua_mret_get(0);", .{});
                    self.pl("_gf_s = lua_mret_get(1);", .{});
                    self.pl("_gf_var = lua_mret_get(2);", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("} else if (lua_mret_n >= 1) {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = lua_mret_get(0);", .{});
                    self.pl("_gf_s = lua_mret_get(1);", .{});
                    self.pl("_gf_var = lua_val_nil();", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("} else {\n") catch {};
                    self.indent += 1;
                    self.pl("_gf_f = _gf_tmp;", .{});
                    self.pl("_gf_s = lua_val_nil();", .{});
                    self.pl("_gf_var = lua_val_nil();", .{});
                    self.indent -= 1;
                    self.ind();
                    self.w.writeAll("}\n") catch {};
                    self.ind();
                    self.pl("while (1) {{", .{});
                    self.indent += 1;
                    self.ind();
                    self.pl("lua_Value _gf_argv[2] = {{ _gf_s, _gf_var }};", .{});
                    self.ind();
                    self.pl("lua_Value _gf_r0 = lua_invoke(_gf_f, 2, _gf_argv);", .{});
                    self.ind();
                    self.pl("_gf_var = _gf_r0;", .{});
                    self.ind();
                    self.pl("if (_gf_r0.type == VAL_NIL) break;", .{});
                    for (gf.vars, 0..) |vname, vi| {
                        self.ind();
                        if (vi == 0) {
                            self.pl("lua_Value {s} = _gf_r0;", .{vname});
                        } else {
                            self.pl("lua_Value {s} = lua_mret_get({d});", .{ vname, vi - 1 });
                        }
                    }
                    {
                        try self.push_break_scope();
                        defer self.pop_break_scope();
                        try self.emit_block(&gf.body);
                    }
                    self.indent -= 1;
                    self.ind();
                    self.pl("}}", .{});
                    self.indent -= 1;
                    self.pl("}}", .{});
                }
            },
            .do_block => |*db| {
                self.pl("{{", .{});
                self.indent += 1;
                try self.emit_block(&db.body);
                self.indent -= 1;
                self.pl("}}", .{});
            },
            .func_decl => |*fd| {
                if (fd.path.len == 1 and !fd.method) {
                    try self.note_comptime_func(fd.path[0], &fd.func);
                }
                if (fd.is_local) {
                    // Hoisted to file scope in emit_module.
                }
            },
            // NOTE: there is no `.struct_def` case. Anonymous record
            // bindings don't need a top-level emission — they are handled
            // inline at the binding site.
            .match_stmt => |match_stmt| {
                self.ind();
                try self.emit_match_expr(match_stmt);
                self.p(";\n", .{});
            },
            .try_stmt => |try_stmt| {
                try self.emit_try_stmt(try_stmt);
            },
            .defer_stmt => |*defer_stmt| {
                // Register the body to run on scope exit (LIFO). The actual
                // emission happens at block end (`emit_top_defers`) and before
                // early returns (`emit_all_pending_defers`). `&defer_stmt.body`
                // points into the stable AST, so it stays valid.
                try self.note_defer(&defer_stmt.body);
            },
            .enum_def => |*ed| try self.emit_enum_descriptor(ed),
            .concept_def => |*cd| try self.emit_concept_descriptor(cd),
            .alias_def => {},
            .brk => {
                if (self.has_pending_defers()) {
                    try self.emit_pending_defers_from(self.current_break_scope_base());
                }
                self.pl("break;", .{});
            },
            .cont => {
                if (self.has_pending_defers()) {
                    try self.emit_pending_defers_from(self.current_break_scope_base());
                }
                self.pl("continue;", .{});
            },
            .goto_stmt => |g| self.pl("goto {s};", .{g.label}),
            .label_stmt => |l| self.pl("{s}:;", .{l.label}),
        }
    }

    fn derive_arg_count(args: ?[]const u8) usize {
        const raw = args orelse return 0;
        var count: usize = 0;
        var it = std.mem.splitScalar(u8, raw, ',');
        while (it.next()) |part| {
            if (std.mem.trim(u8, part, " \t\r\n").len != 0) count += 1;
        }
        return count;
    }

    fn enum_derive_count(attrs: []const ast.Attribute) usize {
        var count: usize = 0;
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            count += derive_arg_count(attr.args);
        }
        return count;
    }

    fn strip_attribute_string(raw: []const u8) []const u8 {
        const trimmed = std.mem.trim(u8, raw, " \t\r\n");
        if (trimmed.len >= 2 and trimmed[0] == '"' and trimmed[trimmed.len - 1] == '"') {
            return trimmed[1 .. trimmed.len - 1];
        }
        return trimmed;
    }

    fn attrs_have_derive(attrs: []const ast.Attribute, derive_name: []const u8) bool {
        for (attrs) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                if (std.mem.eql(u8, strip_attribute_string(part), derive_name)) return true;
            }
        }
        return false;
    }

    fn enum_has_derive_descriptor(self: *const CodeGen, enum_name: []const u8) bool {
        const ed = self.enum_defs.get(enum_name) orelse return false;
        return enum_derive_count(ed.attributes) > 0;
    }

    fn emit_enum_descriptor(self: *CodeGen, ed: *const ast.EnumDef) E!void {
        const derive_count = enum_derive_count(ed.attributes);
        if (derive_count == 0) return;

        try self.note_local(ed.name);
        self.ind();
        self.pl("lua_Value {s} = lua_table_new_with_capacity(0, 4);", .{ed.name});
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"__duo_kind\", {d}, 10, lua_val_lit(\"enum\"));", .{ ed.name, calc_lua_hash("__duo_kind") });
        self.ind();
        self.p("lua_table_set_raw_lit({s}, \"name\", {d}, 4, lua_val_lit(\"", .{ ed.name, calc_lua_hash("name") });
        try self.emit_string_escaped(ed.name);
        self.p("\"));\n", .{});

        self.ind();
        self.pl("lua_Value {s}_variants = lua_table_new_with_capacity({d}, 0);", .{ ed.name, ed.variants.len });
        for (ed.variants, 0..) |variant, i| {
            const has_payload = variant.payload != null and variant.payload.?.len > 0;
            self.ind();
            self.pl("lua_Value {s}_variant_{d} = lua_table_new_with_capacity(0, 3);", .{ ed.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_variant_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ ed.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(variant.name);
            self.p("\"));\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_variant_{d}, \"tag\", {d}, 3, lua_val_from_int({d}));", .{ ed.name, i, calc_lua_hash("tag"), i });
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_variant_{d}, \"has_payload\", {d}, 11, lua_val_from_bool({s}));", .{ ed.name, i, calc_lua_hash("has_payload"), if (has_payload) "true" else "false" });
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_variants, {d}, {s}_variant_{d});", .{ ed.name, i + 1, ed.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"variants\", {d}, 8, {s}_variants);", .{ ed.name, calc_lua_hash("variants"), ed.name });

        self.ind();
        self.pl("lua_Value {s}_derives = lua_table_new_with_capacity({d}, 0);", .{ ed.name, derive_count });
        var derive_index: usize = 1;
        for (ed.attributes) |attr| {
            if (!std.mem.eql(u8, attr.name, "derive")) continue;
            const raw = attr.args orelse continue;
            var it = std.mem.splitScalar(u8, raw, ',');
            while (it.next()) |part| {
                const derive_name = strip_attribute_string(part);
                if (derive_name.len == 0) continue;
                self.ind();
                self.p("lua_table_set_raw_i64({s}_derives, {d}, lua_val_lit(\"", .{ ed.name, derive_index });
                try self.emit_string_escaped(derive_name);
                self.p("\"));\n", .{});
                derive_index += 1;
            }
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"derives\", {d}, 7, {s}_derives);", .{ ed.name, calc_lua_hash("derives"), ed.name });
    }

    fn emit_concept_descriptor(self: *CodeGen, cd: *const ast.ConceptDef) E!void {
        try self.note_local(cd.name);
        self.ind();
        self.pl("lua_Value {s} = lua_table_new_with_capacity(0, 4);", .{cd.name});
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"__duo_kind\", {d}, 10, lua_val_lit(\"concept\"));", .{ cd.name, calc_lua_hash("__duo_kind") });
        self.ind();
        self.p("lua_table_set_raw_lit({s}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, calc_lua_hash("name") });
        try self.emit_string_escaped(cd.name);
        self.p("\"));\n", .{});

        self.ind();
        self.pl("lua_Value {s}_fields = lua_table_new_with_capacity({d}, 0);", .{ cd.name, cd.required_fields.len });
        for (cd.required_fields, 0..) |field, i| {
            self.ind();
            self.pl("lua_Value {s}_field_{d} = lua_table_new_with_capacity(0, 2);", .{ cd.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_field_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(field.name);
            self.p("\"));\n", .{});
            self.ind();
            self.p("lua_table_set_raw_lit({s}_field_{d}, \"type\", {d}, 4, ", .{ cd.name, i, calc_lua_hash("type") });
            try self.emit_type_expr_metadata(field.typ);
            self.p(");\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_fields, {d}, {s}_field_{d});", .{ cd.name, i + 1, cd.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"required_fields\", {d}, 15, {s}_fields);", .{ cd.name, calc_lua_hash("required_fields"), cd.name });

        self.ind();
        self.pl("lua_Value {s}_methods = lua_table_new_with_capacity({d}, 0);", .{ cd.name, cd.required_methods.len });
        for (cd.required_methods, 0..) |method, i| {
            self.ind();
            self.pl("lua_Value {s}_method_{d} = lua_table_new_with_capacity(0, 3);", .{ cd.name, i });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_method_{d}, \"name\", {d}, 4, lua_val_lit(\"", .{ cd.name, i, calc_lua_hash("name") });
            try self.emit_string_escaped(method.name);
            self.p("\"));\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_lit({s}_method_{d}, \"param_count\", {d}, 11, lua_val_from_num({d}));", .{ cd.name, i, calc_lua_hash("param_count"), method.params.len });
            self.ind();
            self.p("lua_table_set_raw_lit({s}_method_{d}, \"return\", {d}, 6, ", .{ cd.name, i, calc_lua_hash("return") });
            try self.emit_type_expr_metadata(method.ret_type);
            self.p(");\n", .{});
            self.ind();
            self.pl("lua_table_set_raw_i64({s}_methods, {d}, {s}_method_{d});", .{ cd.name, i + 1, cd.name, i });
        }
        self.ind();
        self.pl("lua_table_set_raw_lit({s}, \"required_methods\", {d}, 16, {s}_methods);", .{ cd.name, calc_lua_hash("required_methods"), cd.name });
    }

    fn emit_type_expr_metadata(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        self.p("lua_val_from_str(\"", .{});
        try self.emit_type_expr_metadata_inner(type_expr);
        self.p("\")", .{});
    }

    fn emit_type_expr_metadata_inner(self: *CodeGen, type_expr: ast.TypeExpr) E!void {
        switch (type_expr) {
            .inferred => try self.emit_string_escaped("any"),
            .named => |name| try self.emit_string_escaped(name),
            .pointer => |child| {
                try self.emit_string_escaped("*");
                try self.emit_type_expr_metadata_inner(child.*);
            },
            .optional => |child| {
                try self.emit_string_escaped("?");
                try self.emit_type_expr_metadata_inner(child.*);
            },
            .array => |arr| {
                if (arr.size) |size| {
                    self.p("[{d}]", .{size});
                } else {
                    try self.emit_string_escaped("[]");
                }
                try self.emit_type_expr_metadata_inner(arr.elem.*);
            },
            .func => try self.emit_string_escaped("function"),
            .record => try self.emit_string_escaped("table"),
            .tuple => try self.emit_string_escaped("tuple"),
            .generic => |g| {
                try self.emit_type_expr_metadata_inner(g.base.*);
                try self.emit_string_escaped("[");
                for (g.params, 0..) |param, i| {
                    if (i > 0) try self.emit_string_escaped(",");
                    try self.emit_type_expr_metadata_inner(param);
                }
                try self.emit_string_escaped("]");
            },
        }
    }

    // ── print() special case ──────────────────────────────────────────────────

    fn emit_print_call(self: *CodeGen, args: []*ast.Expr) E!void {
        if (args.len == 0) {
            self.p("puts(\"\");\n", .{});
            return;
        }
        // Build format string based on arg types
        var fmt_buf: std.ArrayList(u8) = .empty;
        defer fmt_buf.deinit(self.alloc);
        var has_sep = false;
        for (args) |arg| {
            if (has_sep) try fmt_buf.appendSlice(self.alloc, "\\t");
            has_sep = true;
            const t = self.expr_type(arg);
            const spec: []const u8 = switch (t) {
                .i8, .i16, .i32 => "%d",
                .i64 => "%lld",
                .u8, .u16, .u32 => "%u",
                .u64 => "%llu",
                .f32, .f64 => "%.17g",
                .bool => "%s",
                .str => "%s",
                else => "%s",
            };
            try fmt_buf.appendSlice(self.alloc, spec);
        }
        try fmt_buf.appendSlice(self.alloc, "\\n");
        self.p("printf(\"{s}\"", .{fmt_buf.items});
        for (args) |arg| {
            self.p(", ", .{});
            const t = self.expr_type(arg);
            if (t == .bool) {
                self.p("(", .{});
                try self.emit_expr(arg);
                self.p(") ? \"true\" : \"false\"", .{});
            } else if (t == .any) {
                self.p("lua_to_str(", .{});
                try self.emit_expr(arg);
                self.p(")", .{});
            } else if (t == .str or arg.* == .string_lit) {
                if (self.expr_emits_lua_value(arg)) {
                    self.p("lua_to_str(", .{});
                    try self.emit_expr(arg);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(arg);
                }
            } else {
                try self.emit_expr(arg);
            }
        }
        self.p(");\n", .{});
    }

    fn emit_dynamic_unbox(self: *CodeGen, e: *const ast.Expr, want: RT) E!void {
        const et = self.expr_type(e);
        if (want != .str and want != .bool and et.is_numeric()) {
            if (want == .f64 and et != .f64) {
                self.p("(double)(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            } else if (want == .i64 and et == .f64) {
                self.p("(int64_t)(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            } else {
                try self.emit_expr(e);
            }
            return;
        }
        switch (want) {
            .str => {
                self.p("lua_to_str(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            },
            .bool => {
                self.p("lua_to_bool(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            },
            .f64 => {
                self.p("(double)lua_to_num(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            },
            else => {
                self.p("(int64_t)lua_to_num(", .{});
                try self.emit_expr(e);
                self.p(")", .{});
            },
        }
    }

    /// True when a `.any` binop operand is a table field/index (or numeric call)
    /// whose value is known to be numeric — safe to unbox without skipping metamethods
    /// on arbitrary userdata/table objects.
    fn dynamic_binop_operand_is_numeric_access(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            // Table field reads on dynamic objects; emit unboxes when the value is numeric.
            .field => true,
            .index => |idx| self.expr_type(e).is_numeric() or
                (self.expr_type(idx.obj) == .any and self.is_integer_key(idx.key)),
            .call => self.expr_type(e).is_numeric(),
            .unop => |u| u.op == .neg and self.dynamic_binop_operand_is_numeric_access(u.operand),
            else => false,
        };
    }

    /// Dynamic table field/index read on a `.any` object — still runs full `lua_table_get`
    /// (including `__index`), but pairs with a numeric-marked local in one-sided binops.
    fn dynamic_binop_operand_is_dynamic_table_read(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .field => self.expr_type(e.field.obj) == .any,
            .index => self.expr_type(e.index.obj) == .any,
            else => false,
        };
    }

    /// Operand safe to treat as a number in a native binop when the other side
    /// is also safe. Bare `.name` locals only qualify after numeric assignment.
    fn dynamic_binop_operand_is_safe_native_unbox(self: *CodeGen, e: *const ast.Expr) bool {
        return switch (e.*) {
            .int_lit, .float_lit => true,
            .name => |n| self.is_numeric_lua_local(n.ident),
            else => self.dynamic_binop_operand_is_numeric_access(e),
        };
    }

    /// Both operands are `.any` but each can be unboxed without metamethod dispatch.
    fn try_emit_both_any_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        if (!self.dynamic_binop_operand_is_safe_native_unbox(lhs)) return false;
        if (!self.dynamic_binop_operand_is_safe_native_unbox(rhs)) return false;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(lhs) or self.expr_tree_has_float(rhs);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(lhs, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(rhs, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// One operand is a numeric-marked `lua_Value` local (or literal); the other is a
    /// dynamic table read with a non-numeric key/param. Unbox the local side only.
    fn try_emit_one_sided_any_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        if (lt != .any or rt != .any) return false;
        const lhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(lhs);
        const rhs_safe = self.dynamic_binop_operand_is_safe_native_unbox(rhs);
        if (lhs_safe and rhs_safe) return false;

        const pair: struct { safe: *const ast.Expr, read: *const ast.Expr } = if (lhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(rhs) and !rhs_safe)
            .{ .safe = lhs, .read = rhs }
        else if (rhs_safe and self.dynamic_binop_operand_is_dynamic_table_read(lhs) and !lhs_safe)
            .{ .safe = rhs, .read = lhs }
        else
            return false;
        const safe_expr = pair.safe;
        const read_expr = pair.read;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        const use_float = op == .div or self.expr_tree_has_float(safe_expr) or self.expr_tree_has_float(read_expr);
        const unbox_t: RT = if (use_float) .f64 else .i64;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(safe_expr, unbox_t);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(read_expr, unbox_t);
                self.p(")", .{});
                return true;
            },
            .idiv => {
                self.p("lua_idiv_i64(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            .mod => {
                self.p("lua_imod_i64(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                self.p("(", .{});
                try self.emit_dynamic_unbox(safe_expr, .i64);
                self.p(" {s} ", .{binop_str(op)});
                try self.emit_dynamic_unbox(read_expr, .i64);
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    /// When exactly one binop operand is a native scalar and the other is `.any`,
    /// emit a direct C operator with a single unbox on the dynamic side.
    fn try_emit_mixed_native_binop(
        self: *CodeGen,
        op: ast.BinOp,
        lhs: *const ast.Expr,
        rhs: *const ast.Expr,
        lt: RT,
        rt: RT,
    ) E!bool {
        const native_t: RT = if (lt.is_native() and lt != .any and rt == .any)
            lt
        else if (rt.is_native() and rt != .any and lt == .any)
            rt
        else
            return false;
        const native_is_lhs = lt.eql(native_t);
        const any_expr = if (native_is_lhs) rhs else lhs;
        const native_expr = if (native_is_lhs) lhs else rhs;
        const via_any_unbox = self.dynamic_binop_operand_is_safe_native_unbox(any_expr);
        const via_native_access = self.dynamic_binop_operand_is_numeric_access(native_expr);
        if (!via_any_unbox and !via_native_access) return false;
        // Unbox the `.any` side; the native side is either a typed local or a
        // numeric table access that already lowers to a native scalar.
        const dynamic = any_expr;

        switch (op) {
            .concat, .pow, .contains, .matmul, .pipeline => return false,
            else => {},
        }

        if (op == .@"and" or op == .@"or") {
            if (native_t != .bool) return false;
            if (op == .@"or") {
                self.p("((", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") ? (", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") : (", .{});
                try self.emit_dynamic_unbox(dynamic, .bool);
                self.p("))", .{});
            } else {
                self.p("((", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p(") ? (", .{});
                try self.emit_dynamic_unbox(dynamic, .bool);
                self.p(") : (", .{});
                try self.emit_expr(if (native_is_lhs) lhs else rhs);
                self.p("))", .{});
            }
            return true;
        }

        if ((op == .eq or op == .neq) and native_t == .str) {
            if (!self.expr_is_native_cstr(if (native_is_lhs) lhs else rhs)) return false;
            self.p("(strcmp(", .{});
            if (native_is_lhs) {
                try self.emit_expr(lhs);
                self.p(", ", .{});
                try self.emit_dynamic_unbox(rhs, .str);
            } else {
                try self.emit_dynamic_unbox(lhs, .str);
                self.p(", ", .{});
                try self.emit_expr(rhs);
            }
            self.p(") {s} 0)", .{if (op == .eq) "==" else "!="});
            return true;
        }

        if (native_t == .bool) return false;

        const use_float = native_t == .f64 or op == .div or self.expr_tree_has_float(dynamic);
        const unbox_t: RT = if (use_float) .f64 else if (native_t.is_integer()) .i64 else native_t;

        switch (op) {
            .add, .sub, .mul, .div, .eq, .neq, .lt, .gt, .leq, .geq => {
                self.p("(", .{});
                if (native_is_lhs) {
                    try self.emit_expr(lhs);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_dynamic_unbox(rhs, unbox_t);
                } else {
                    try self.emit_dynamic_unbox(lhs, unbox_t);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_expr(rhs);
                }
                self.p(")", .{});
                return true;
            },
            .idiv => {
                if (native_is_lhs) {
                    self.p("lua_idiv_i64((int64_t)(", .{});
                    try self.emit_expr(lhs);
                    self.p("), ", .{});
                    try self.emit_dynamic_unbox(rhs, .i64);
                    self.p(")", .{});
                } else {
                    self.p("lua_idiv_i64(", .{});
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(", (int64_t)(", .{});
                    try self.emit_expr(rhs);
                    self.p("))", .{});
                }
                return true;
            },
            .mod => {
                if (native_is_lhs) {
                    self.p("lua_imod_i64((int64_t)(", .{});
                    try self.emit_expr(lhs);
                    self.p("), ", .{});
                    try self.emit_dynamic_unbox(rhs, .i64);
                    self.p(")", .{});
                } else {
                    self.p("lua_imod_i64(", .{});
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(", (int64_t)(", .{});
                    try self.emit_expr(rhs);
                    self.p("))", .{});
                }
                return true;
            },
            .band, .bor, .bxor, .lshift, .rshift => {
                if (!native_t.is_integer()) return false;
                self.p("(", .{});
                if (native_is_lhs) {
                    try self.emit_expr(lhs);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_dynamic_unbox(rhs, .i64);
                } else {
                    try self.emit_dynamic_unbox(lhs, .i64);
                    self.p(" {s} ", .{binop_str(op)});
                    try self.emit_expr(rhs);
                }
                self.p(")", .{});
                return true;
            },
            else => return false,
        }
    }

    fn emit_as_lua_value(self: *CodeGen, expr: *const ast.Expr) E!void {
        if (expr.* == .name) {
            if (self.vararg_funcs.get(expr.name.ident)) |argv_cname| {
                self.p("lua_val_from_func((void*){s}__argv)", .{argv_cname});
                return;
            }
        }
        if (expr.* == .string_lit) {
            const hash = calc_lua_hash(expr.string_lit.val);
            self.p("lua_val_from_literal(\"", .{});
            try self.emit_string_escaped(expr.string_lit.val);
            self.p("\", {d}, {d})", .{ hash, expr.string_lit.val.len });
            return;
        }
        const t = self.expr_type(expr);
        switch (t) {
            .str => {
                if (self.expr_emits_lua_value(expr)) {
                    try self.emit_expr(expr);
                } else {
                    self.p("lua_val_from_str(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                }
            },
            .i8, .i16, .i32, .i64, .u8, .u16, .u32, .u64 => {
                self.p("lua_val_from_int((int64_t)(", .{});
                if (self.expr_emits_lua_value(expr)) {
                    self.p("lua_to_num(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(expr);
                }
                self.p("))", .{});
            },
            .f32, .f64 => {
                self.p("lua_val_from_num((double)(", .{});
                if (self.expr_emits_lua_value(expr)) {
                    self.p("lua_to_num(", .{});
                    try self.emit_expr(expr);
                    self.p(")", .{});
                } else {
                    try self.emit_expr(expr);
                }
                self.p("))", .{});
            },
            .bool => {
                self.p("lua_val_from_bool(", .{});
                try self.emit_expr(expr);
                self.p(")", .{});
            },
            .func => {
                if (expr.* == .func_expr) {
                    try self.emit_expr(expr);
                } else {
                    try self.emit_native_func_as_lua_value(expr);
                }
            },
            .any => {
                try self.emit_expr(expr);
            },
            else => {
                self.p("lua_val_nil()", .{});
            },
        }
    }

    fn emit_bound_field_call(self: *CodeGen, c: anytype) E!void {
        const f = c.func.field;
        const hash = calc_lua_hash(f.field);
        self.p("({{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Value __self = ", .{});
        try self.emit_as_lua_value(f.obj);
        self.p(";\n", .{});
        self.ind();
        self.p("lua_Value __fn = lua_table_get_str_lit(__self, \"{s}\", {d}u, {d});\n", .{ f.field, hash, f.field.len });
        self.ind();
        self.p("lua_Value __argv[{d}] = {{__self", .{c.args.len + 1});
        for (c.args) |arg| {
            self.p(", ", .{});
            try self.emit_as_lua_value(arg);
        }
        self.p("}};\n", .{});
        self.ind();
        self.p("lua_invoke(__fn, {d}, __argv);\n", .{c.args.len + 1});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    // ── Expressions ───────────────────────────────────────────────────────────

    fn emit_num_for_bound(self: *CodeGen, expr: *const ast.Expr, vt: RT) E!void {
        if (self.expr_type(expr) == .any and !self.expr_is_raw_c_intrinsic(expr)) {
            self.p("(", .{});
            self.typ(vt);
            self.p(")lua_to_num(", .{});
            try self.emit_as_lua_value(expr);
            self.p(")", .{});
        } else {
            try self.emit_expr(expr);
        }
    }

    /// True when the expression is the nil literal.
    fn expr_is_nil_lit(self: *CodeGen, e: *const ast.Expr) bool {
        _ = self;
        return e.* == .nil;
    }

    /// True when a native (non-any, non-pointer) typed value can never hold nil.
    fn expr_is_typed_non_nil(self: *CodeGen, e: *const ast.Expr) bool {
        const t = self.expr_type(e);
        return t != .any and t != .nil and t != .str and t != .func and t != .pointer;
    }

    fn emit_list_comprehension(self: *CodeGen, lc: ast.ListComprehension) E!void {
        self.p("({{\n", .{});
        self.indent += 1;
        try self.push_local_scope();
        defer self.pop_local_scope();

        self.ind();
        self.p("lua_Value tmp = lua_table_new();\n", .{});
        self.ind();
        self.p("lua_Value tbl = ", .{});
        try self.emit_as_lua_value(lc.iter);
        self.p(";\n", .{});
        self.ind();
        self.p("int out_idx = 1;\n", .{});
        self.ind();
        self.p("if (tbl.type == VAL_TABLE) {{\n", .{});
        self.indent += 1;
        self.ind();
        self.p("lua_Table* t_ptr = (lua_Table*)tbl.as.tval;\n", .{});

        if (lc.key_name) |key_name| {
            try self.note_local(key_name);
            try self.note_local(lc.value_name);

            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("if (t_ptr->array[_gf_idx].type == VAL_NIL) continue;\n", .{});
            self.ind();
            self.p("lua_Value {s} = lua_val_from_num((double)(_gf_idx + 1));\n", .{key_name});
            self.ind();
            self.p("lua_Value {s} = t_ptr->array[_gf_idx];\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});

            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->capacity; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("if (t_ptr->hash_keys[_gf_idx].type == VAL_NIL) continue;\n", .{});
            self.ind();
            self.p("lua_Value {s} = t_ptr->hash_keys[_gf_idx];\n", .{key_name});
            self.ind();
            self.p("lua_Value {s} = t_ptr->hash_vals[_gf_idx];\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        } else {
            try self.note_local(lc.value_name);
            self.ind();
            self.p("for (int _gf_idx = 0; _gf_idx < t_ptr->array_size; _gf_idx++) {{\n", .{});
            self.indent += 1;
            self.ind();
            self.p("lua_Value {s} = t_ptr->array[_gf_idx];\n", .{lc.value_name});
            self.ind();
            self.p("if ({s}.type == VAL_NIL) break;\n", .{lc.value_name});
            try self.emit_list_comprehension_append(lc);
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }

        self.indent -= 1;
        self.ind();
        self.p("}}\n", .{});
        self.ind();
        self.p("tmp;\n", .{});
        self.indent -= 1;
        self.ind();
        self.p("}})", .{});
    }

    fn emit_list_comprehension_append(self: *CodeGen, lc: ast.ListComprehension) E!void {
        if (lc.filter) |filter| {
            self.ind();
            self.p("if (", .{});
            try self.emit_lua_truthy_expr(filter);
            self.p(") {{\n", .{});
            self.indent += 1;
        }
        self.ind();
        self.p("lua_table_set_raw_i64(tmp, out_idx++, ", .{});
        try self.emit_as_lua_value(lc.value);
        self.p(");\n", .{});
        if (lc.filter != null) {
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }
    }

    fn emit_expr(self: *CodeGen, expr: *const ast.Expr) E!void {
        switch (expr.*) {
            .quote, .unquote, .macro_call => self.p("/* unexpanded macro expression */ lua_val_nil()", .{}),
            .sequence => |seq| {
                // In single-value context, emit first expression; rest are side effects.
                if (seq.exprs.len > 0) {
                    try self.emit_expr(seq.exprs[0]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
            },
            .nil => self.p("NULL", .{}),
            .true_lit => self.p("true", .{}),
            .false_lit => self.p("false", .{}),
            .int_lit => |v| self.p("{d}", .{v.val}),
            .float_lit => |v| self.p("{d}", .{v.val}),
