            },
            .binop => |b| {
                // ── Typed-value vs nil comparison ─────────────────────────
                // A value of a concrete native type (i64, f64, bool, ...) can
                // never be nil, so `x == nil` is always false and `x ~= nil` is
                // always true.  Emitting the literal avoids generating invalid C
                // like `width == NULL` for an integer.
                if (b.op == .eq or b.op == .neq) {
                    const nil_side = if (self.expr_is_nil_lit(b.lhs)) b.rhs else if (self.expr_is_nil_lit(b.rhs)) b.lhs else null;
                    if (nil_side) |side| {
                        if (self.expr_is_typed_non_nil(side)) {
                            self.p("{s}", .{if (b.op == .eq) "0" else "1"});
                            return;
                        }
                    }
                }

                // ── Compile-time constant folding ─────────────────────────
                // When both operands are integer literals, compute the result
                // now and emit it as a plain C integer constant.  This avoids
                // boxing through lua_Value and lets the downstream C compiler
                // see the concrete value for further constant propagation.
                if (b.lhs.* == .int_lit and b.rhs.* == .int_lit) {
                    const lv = b.lhs.int_lit.val;
                    const rv = b.rhs.int_lit.val;
                    switch (b.op) {
                        .add => {
                            self.p("{d}", .{lv +% rv});
                            return;
                        },
                        .sub => {
                            self.p("{d}", .{lv -% rv});
                            return;
                        },
                        .mul => {
                            self.p("{d}", .{lv *% rv});
                            return;
                        },
                        .idiv => if (rv != 0) {
                            self.p("{d}", .{@divFloor(lv, rv)});
                            return;
                        },
                        .mod => if (rv != 0) {
                            self.p("{d}", .{@mod(lv, rv)});
                            return;
                        },
                        .band => {
                            self.p("{d}", .{lv & rv});
                            return;
                        },
                        .bor => {
                            self.p("{d}", .{lv | rv});
                            return;
                        },
                        .bxor => {
                            self.p("{d}", .{lv ^ rv});
                            return;
                        },
                        .lshift => if (rv >= 0 and rv < 64) {
                            self.p("{d}", .{lv << @intCast(rv)});
                            return;
                        },
                        .rshift => if (rv >= 0 and rv < 64) {
                            self.p("{d}", .{@as(i64, @bitCast(@as(u64, @bitCast(lv)) >> @intCast(rv)))});
                            return;
                        },
                        .eq => {
                            self.p("{s}", .{if (lv == rv) "1" else "0"});
                            return;
                        },
                        .neq => {
                            self.p("{s}", .{if (lv != rv) "1" else "0"});
                            return;
                        },
                        .lt => {
                            self.p("{s}", .{if (lv < rv) "1" else "0"});
                            return;
                        },
                        .gt => {
                            self.p("{s}", .{if (lv > rv) "1" else "0"});
                            return;
                        },
                        .leq => {
                            self.p("{s}", .{if (lv <= rv) "1" else "0"});
                            return;
                        },
                        .geq => {
