                        .band => "lua_band",
                        .bor => "lua_bor",
                        .bxor => "lua_bxor",
                        .lshift => "lua_lshift",
                        .rshift => "lua_rshift",
                        .eq => "lua_eq",
                        .neq => "lua_neq",
                        .lt => "lua_lt",
                        .gt => "lua_gt",
