                                    try self.emit_expr(b.lhs);
                                    self.p(") % {d})", .{b.rhs.int_lit.val});
                                } else {
                                    self.p("lua_imod_i64((int64_t)(", .{});
                                    try self.emit_expr(b.lhs);
                                    self.p("), (int64_t)(", .{});
                                    try self.emit_expr(b.rhs);
                                    self.p("))", .{});
