                                self.p(") - (double)(", .{});
                                try self.emit_expr(b.rhs);
                                self.p(") * floor((double)(", .{});
                                try self.emit_expr(b.lhs);
                                self.p(") / (double)(", .{});
                                try self.emit_expr(b.rhs);
                                self.p("))))", .{});
                            }
