                                    try self.emit_expr(b.lhs);
                                    self.p(") ? (", .{});
                                    try self.emit_expr(b.lhs);
                                    self.p(") : (", .{});
                                    try self.emit_expr(b.rhs);
                                    self.p("))", .{});
