            if (args.len > 0) try self.emit_expr(args[0]);
            self.p(", ", .{});
            if (args.len > 1) try self.emit_expr(args[1]) else self.p("0", .{});
            self.p(", ", .{});
            if (args.len > 2) try self.emit_expr(args[2]) else self.p("0", .{});
