            try self.emit_expr(args[1]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[2]);
            self.p("))", .{});
            return true;
        }
        if (std.mem.eql(u8, fname, "matmul_f32") and args.len >= 6) {
            self.p("duo_simd_matmul_f32((const float*)(", .{});
            try self.emit_expr(args[0]);
            self.p("), (const float*)(", .{});
            try self.emit_expr(args[1]);
            self.p("), (float*)(", .{});
            try self.emit_expr(args[2]);
            self.p("), (size_t)(", .{});
            try self.emit_expr(args[3]);
