            return true;
        } else if (std.mem.eql(u8, mod, "utf8")) {
            const mapped = if (std.mem.eql(u8, fname, "char")) "lua_str_char" else if (std.mem.eql(u8, fname, "len")) "lua_utf8_len" else if (std.mem.eql(u8, fname, "codepoint")) "lua_utf8_codepoint" else if (std.mem.eql(u8, fname, "offset")) "lua_utf8_offset" else if (std.mem.eql(u8, fname, "codes")) "lua_utf8_codes" else return false;

            const expected: usize = if (std.mem.eql(u8, fname, "len") or std.mem.eql(u8, fname, "codes")) @as(usize, 1) else if (std.mem.eql(u8, fname, "offset")) @as(usize, 3) else if (std.mem.eql(u8, fname, "codepoint")) @as(usize, 3) else if (std.mem.eql(u8, fname, "char")) @as(usize, 4) else 0;

            try self.emit_boxed_runtime_call(mapped, args, expected, result_rt);
            return true;
        } else if (std.mem.eql(u8, mod, "debug")) {
            const mapped = if (std.mem.eql(u8, fname, "traceback")) "lua_debug_traceback" else if (std.mem.eql(u8, fname, "getinfo")) "lua_debug_getinfo" else return false;

            const expected: usize = if (std.mem.eql(u8, fname, "traceback")) @as(usize, 0) else if (std.mem.eql(u8, fname, "getinfo")) @as(usize, 2) else 0;

            try self.emit_boxed_runtime_call(mapped, args, expected, result_rt);
            return true;
        } else if (std.mem.eql(u8, mod, "package")) {
            const mapped = if (std.mem.eql(u8, fname, "searchpath")) "lua_package_searchpath" else return false;

            const expected: usize = if (std.mem.eql(u8, fname, "searchpath")) @as(usize, 4) else 0;

            self.p("{s}(", .{mapped});
            var i: usize = 0;
            while (i < expected) : (i += 1) {
                if (i > 0) self.p(", ", .{});
                if (i < args.len) {
                    try self.emit_as_lua_value(args[i]);
                } else {
                    self.p("lua_val_nil()", .{});
                }
            }
            self.p(")", .{});
            return true;
        } else if (std.mem.eql(u8, mod, "jit")) {
            const mapped = if (std.mem.eql(u8, fname, "on")) "lua_jit_on" else if (std.mem.eql(u8, fname, "off")) "lua_jit_off" else if (std.mem.eql(u8, fname, "flush")) "lua_jit_flush" else if (std.mem.eql(u8, fname, "status")) "lua_jit_status" else if (std.mem.eql(u8, fname, "version_num")) "lua_jit_version_num" else if (std.mem.eql(u8, fname, "opt")) "lua_jit_opt" else return false;

            const expected: usize = if (std.mem.eql(u8, fname, "on") or std.mem.eql(u8, fname, "off") or std.mem.eql(u8, fname, "flush")) @as(usize, 1) else if (std.mem.eql(u8, fname, "status") or std.mem.eql(u8, fname, "version_num")) @as(usize, 0) else if (std.mem.eql(u8, fname, "opt")) @as(usize, 2) else 0;

            try self.emit_boxed_runtime_call(mapped, args, expected, result_rt);
            return true;
        } else if (std.mem.eql(u8, mod, "ffi")) {
            const mapped = if (std.mem.eql(u8, fname, "cdef")) "lua_ffi_cdef" else if (std.mem.eql(u8, fname, "new")) "lua_ffi_new" else if (std.mem.eql(u8, fname, "typeof")) "lua_ffi_typeof" else if (std.mem.eql(u8, fname, "cast")) "lua_ffi_cast" else if (std.mem.eql(u8, fname, "sizeof")) "lua_ffi_sizeof" else if (std.mem.eql(u8, fname, "alignof")) "lua_ffi_alignof" else if (std.mem.eql(u8, fname, "offsetof")) "lua_ffi_offsetof" else if (std.mem.eql(u8, fname, "istype")) "lua_ffi_istype" else if (std.mem.eql(u8, fname, "errno")) "lua_ffi_errno" else if (std.mem.eql(u8, fname, "string")) "lua_ffi_string" else if (std.mem.eql(u8, fname, "copy")) "lua_ffi_copy" else if (std.mem.eql(u8, fname, "fill")) "lua_ffi_fill" else if (std.mem.eql(u8, fname, "load")) "lua_ffi_load" else if (std.mem.eql(u8, fname, "gc")) "lua_ffi_gc" else return false;

            const expected: usize = if (std.mem.eql(u8, fname, "cdef") or std.mem.eql(u8, fname, "typeof") or std.mem.eql(u8, fname, "sizeof") or std.mem.eql(u8, fname, "alignof") or std.mem.eql(u8, fname, "errno") or std.mem.eql(u8, fname, "load")) @as(usize, 1) else if (std.mem.eql(u8, fname, "new") or std.mem.eql(u8, fname, "cast") or std.mem.eql(u8, fname, "istype") or std.mem.eql(u8, fname, "string") or std.mem.eql(u8, fname, "gc")) @as(usize, 2) else if (std.mem.eql(u8, fname, "offsetof") or std.mem.eql(u8, fname, "copy") or std.mem.eql(u8, fname, "fill")) @as(usize, 3) else 0;

            try self.emit_boxed_runtime_call(mapped, args, expected, result_rt);
            return true;
        } else if (std.mem.eql(u8, mod, "net")) {
            const mapped = if (std.mem.eql(u8, fname, "connect")) "duo_net_tcp_connect" else if (std.mem.eql(u8, fname, "listen")) "duo_net_tcp_listen" else if (std.mem.eql(u8, fname, "accept")) "duo_net_tcp_accept" else if (std.mem.eql(u8, fname, "send")) "duo_net_tcp_send" else if (std.mem.eql(u8, fname, "recv")) "duo_net_tcp_recv" else if (std.mem.eql(u8, fname, "close")) "duo_net_tcp_close" else if (std.mem.eql(u8, fname, "udp_socket")) "duo_net_udp_socket_open" else if (std.mem.eql(u8, fname, "udp_sendto")) "duo_net_udp_sendto" else if (std.mem.eql(u8, fname, "udp_recvfrom")) "duo_net_udp_recvfrom" else if (std.mem.eql(u8, fname, "http_get")) "duo_net_http_get" else if (std.mem.eql(u8, fname, "http_post")) "duo_net_http_post" else if (std.mem.eql(u8, fname, "dns_resolve")) "duo_net_dns_resolve" else return false;

            const expected: usize =
                if (std.mem.eql(u8, fname, "accept") or std.mem.eql(u8, fname, "close") or std.mem.eql(u8, fname, "http_get") or std.mem.eql(u8, fname, "dns_resolve")) @as(usize, 1) else if (std.mem.eql(u8, fname, "http_post")) @as(usize, 3) else if (std.mem.eql(u8, fname, "udp_sendto")) @as(usize, 4) else @as(usize, 2);

            if (std.mem.eql(u8, fname, "send") and try self.try_emit_native_net_send(args, result_rt)) return true;
            if (std.mem.eql(u8, fname, "close") and try self.try_emit_native_net_close(args)) return true;
            try self.emit_boxed_runtime_call(mapped, args, expected, result_rt);
            return true;
        }

        return false;
    }

    fn binop_str(op: ast.BinOp) []const u8 {
        return switch (op) {
            .add => "+",
            .sub => "-",
            .mul => "*",
            .div => "/",
            .idiv => "/", // integer division — both operands should be integer
            .mod => "%",
            .pow => "/* ^ */", // handled via pow()
            .band => "&",
            .bor => "|",
            .bxor => "^",
            .lshift => "<<",
            .rshift => ">>",
            .concat => "/* .. */",
            .eq => "==",
            .neq => "!=",
            .lt => "<",
            .gt => ">",
            .leq => "<=",
            .geq => ">=",
            .@"and" => "&&",
            .@"or" => "||",
            .contains => "/* in */",
            .matmul => "/* @ */",
            .pipeline => "/* |> */",
        };
    }

    // ── Closures & require ────────────────────────────────────────────────────

    fn collect_closures_expr(self: *CodeGen, expr: *const ast.Expr, list: *std.ArrayList(*ast.FuncBody)) std.mem.Allocator.Error!void {
        switch (expr.*) {
            .func_expr => |fb| {
                if (fb.closure_id) |id| {
                    if (self.emitted_closures.contains(id)) return;
                    try self.emitted_closures.put(self.alloc, id, {});
                    try list.append(self.alloc, fb);
                }
                try self.collect_closures_block(&fb.body, list);
            },
            .binop => |b| {
                try self.collect_closures_expr(b.lhs, list);
                try self.collect_closures_expr(b.rhs, list);
            },
            .unop => |u| try self.collect_closures_expr(u.operand, list),
            .call => |c| {
                try self.collect_closures_expr(c.func, list);
                for (c.args) |a| try self.collect_closures_expr(a, list);
            },
            .method_call => |mc| {
                try self.collect_closures_expr(mc.obj, list);
                for (mc.args) |a| try self.collect_closures_expr(a, list);
            },
            .field => |f| try self.collect_closures_expr(f.obj, list),
            .index => |idx| {
                try self.collect_closures_expr(idx.obj, list);
                try self.collect_closures_expr(idx.key, list);
            },
            .table => |t| {
                for (t.fields) |fld| {
                    switch (fld) {
                        .indexed => |idx| {
                            try self.collect_closures_expr(idx.key, list);
                            try self.collect_closures_expr(idx.val, list);
                        },
                        .named => |nmd| try self.collect_closures_expr(nmd.val, list),
                        .positional => |pos| try self.collect_closures_expr(pos, list),
                    }
                }
            },
            .sequence => |seq| {
                for (seq.exprs) |e| try self.collect_closures_expr(e, list);
            },
            else => {},
        }
    }

    fn collect_closures_block(self: *CodeGen, block: *const ast.Block, list: *std.ArrayList(*ast.FuncBody)) std.mem.Allocator.Error!void {
        for (block.stmts) |*stmt| try self.collect_closures_stmt(stmt, list);
        // Closures in the implicit return (tail expression) of a block are
        // missed by the stmt loop above. Ward's test suite hits this: the last
        // test.it(...) call in a test.group(...) closure is the tail expression.
        if (block.tail_expr) |expr| try self.collect_closures_expr(expr, list);
    }

    fn collect_closures_stmt(self: *CodeGen, stmt: *const ast.Stmt, list: *std.ArrayList(*ast.FuncBody)) std.mem.Allocator.Error!void {
        switch (stmt.*) {
            .local_decl => |*ld| for (ld.inits) |e| try self.collect_closures_expr(e, list),
            .const_decl => |*cd| try self.collect_closures_expr(cd.val, list),
            .assign => |*as| for (as.values) |v| try self.collect_closures_expr(v, list),
            .ret => |*r| for (r.vals) |v| try self.collect_closures_expr(v, list),
            .if_stmt => |*is| {
                try self.collect_closures_expr(is.cond, list);
                try self.collect_closures_block(&is.then, list);
                for (is.elseifs) |*ei| {
                    try self.collect_closures_expr(ei.cond, list);
                    try self.collect_closures_block(&ei.body, list);
                }
                if (is.else_body) |*eb| try self.collect_closures_block(eb, list);
            },
            .while_loop => |*wl| {
                try self.collect_closures_expr(wl.cond, list);
                try self.collect_closures_block(&wl.body, list);
            },
            .repeat_loop => |*rl| {
                try self.collect_closures_block(&rl.body, list);
                try self.collect_closures_expr(rl.cond, list);
            },
            .num_for => |*nf| try self.collect_closures_block(&nf.body, list),
            .gen_for => |*gf| {
                for (gf.iters) |e| try self.collect_closures_expr(e, list);
                try self.collect_closures_block(&gf.body, list);
            },
            .call_stmt => |*cs| try self.collect_closures_expr(cs.expr, list),
            .expr_stmt => |*es| try self.collect_closures_expr(es.expr, list),
            .do_block => |*db| try self.collect_closures_block(&db.body, list),
            .func_decl => |*fd| try self.collect_closures_block(&fd.func.body, list),
            else => {},
        }
    }

    fn collect_closures_module(self: *CodeGen, mod: *const ast.Module, list: *std.ArrayList(*ast.FuncBody)) !void {
        try self.collect_closures_block(&mod.body, list);
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                try self.collect_closures_block(&stmt.func_decl.func.body, list);
            }
        }
    }

    fn collect_local_funcs_block(self: *CodeGen, block: *const ast.Block, list: *std.ArrayList(*ast.FuncDecl)) std.mem.Allocator.Error!void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .func_decl => |*fd| {
                    // In duo_mode, single-name bare functions are effectively local
                    const effectively_local = fd.is_local or (self.duo_mode and fd.path.len == 1 and !fd.method);
                    if (effectively_local) try list.append(self.alloc, fd);
                    // Do NOT recurse into function bodies — nested local functions
                    // will be emitted when their parent's body is processed.
                },
                .if_stmt => |*is| {
                    try self.collect_local_funcs_block(&is.then, list);
                    for (is.elseifs) |*ei| try self.collect_local_funcs_block(&ei.body, list);
                    if (is.else_body) |*eb| try self.collect_local_funcs_block(eb, list);
                },
                .while_loop => |*wl| try self.collect_local_funcs_block(&wl.body, list),
                .repeat_loop => |*rl| try self.collect_local_funcs_block(&rl.body, list),
                .num_for => |*nf| try self.collect_local_funcs_block(&nf.body, list),
                .gen_for => |*gf| try self.collect_local_funcs_block(&gf.body, list),
                .do_block => |*db| try self.collect_local_funcs_block(&db.body, list),
                else => {},
            }
        }
    }

    fn collect_local_funcs_module(self: *CodeGen, mod: *const ast.Module, list: *std.ArrayList(*ast.FuncDecl)) std.mem.Allocator.Error!void {
        try self.collect_local_funcs_block(&mod.body, list);
        for (mod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                try self.collect_local_funcs_block(&stmt.func_decl.func.body, list);
            }
        }
    }

    fn emit_closure_structs(self: *CodeGen, list: []const *ast.FuncBody) E!void {
        for (list) |fb| {
            const id = fb.closure_id orelse continue;
            self.p("typedef struct {{\n", .{});
            self.p("    duo_ObjHeader header;\n", .{});
            self.p("    int id;\n", .{});
            self.p("    int nup;\n", .{});
            var buf: [256]u8 = undefined;
            for (fb.upvalues, 0..) |up, i| {
                if (upvalue_uses_pointer(up)) {
                    // Mutable upvalue: store pointer to shared cell
                    self.p("    lua_Value* up{d};\n", .{i});
                } else if (up.typ) |t| {
                    if (t == .func) {
                        self.p("    lua_Value up{d};\n", .{i});
                    } else {
                        self.p("    {s} up{d};\n", .{ t.c_type(&buf), i });
                    }
                } else {
                    self.p("    lua_Value up{d};\n", .{i});
                }
            }
            self.p("}} duo_closure_{d};\n\n", .{id});

            self.p("static inline duo_closure_{d}* duo_make_closure_{d}(", .{ id, id });
            for (fb.upvalues, 0..) |up, i| {
                if (i > 0) self.p(", ", .{});
                if (upvalue_uses_pointer(up)) {
                    self.p("lua_Value* up{d}", .{i});
                } else if (up.typ) |t| {
                    if (t == .func) {
                        self.p("lua_Value up{d}", .{i});
                    } else {
                        self.p("{s} up{d}", .{ t.c_type(&buf), i });
                    }
                } else {
                    self.p("lua_Value up{d}", .{i});
                }
            }
            self.p(") {{\n", .{});
            self.p("    duo_closure_{d}* cl = (duo_closure_{d}*)malloc(sizeof(duo_closure_{d}));\n", .{ id, id, id });
            self.p("    cl->header.refcount = 1;\n", .{});
            self.p("    cl->header.type_tag = VAL_CLOSURE;\n", .{});
            self.p("    cl->id = {d};\n", .{id});
            self.p("    cl->nup = {d};\n", .{fb.upvalues.len});
            for (fb.upvalues, 0..) |up, i| {
                self.p("    cl->up{d} = up{d};\n", .{ i, i });
                if (up.typ) |t| {
                    if (t != .func and self.codegen_needs_arc(t)) {
                        self.p("    duo_retain((void*)cl->up{d});\n", .{i});
                    }
                }
            }
            self.p("    return cl;\n", .{});
            self.p("}}\n\n", .{});

            self.p("static void duo_free_closure_{d}(duo_closure_{d}* cl) {{\n", .{ id, id });
            for (fb.upvalues, 0..) |up, i| {
                if (up.typ) |t| {
                    if (t != .func and self.codegen_needs_arc(t)) {
                        self.p("    duo_release((void*)cl->up{d});\n", .{i});
                    }
                }
            }
            self.p("    free(cl);\n", .{});
            self.p("}}\n\n", .{});

            self.p("static lua_Value duo_cl_{d}(lua_Closure* cl, int argc, lua_Value* argv);\n", .{id});
        }
    }

    fn emit_closure_runtime(self: *CodeGen, list: []const *ast.FuncBody) E!void {
        if (list.len == 0) {
            try jit.emitInvokeWrapperPrologue(self);
            self.p("    (void)id; (void)cl; (void)argc; (void)argv;\n", .{});
            self.p("    return lua_val_nil();\n", .{});
            try jit.emitInvokeWrapperEpilogue(self);
            self.p("void duo_free_closure(lua_Closure* cl) {{\n", .{});
            self.p("    (void)cl;\n", .{});
            self.p("}}\n\n", .{});
            return;
        }

        try jit.emitInvokeWrapperPrologue(self);
        for (list) |fb| {
            if (fb.closure_id) |id| {
                self.p("        case {d}: return duo_cl_{d}(cl, argc, argv);\n", .{ id, id });
            }
        }
        try jit.emitInvokeWrapperEpilogue(self);

        self.p("void duo_free_closure(lua_Closure* cl) {{\n", .{});
        self.p("    switch (cl->id) {{\n", .{});
        for (list) |fb| {
            if (fb.closure_id) |id| {
                self.p("        case {d}: duo_free_closure_{d}((duo_closure_{d}*)cl); return;\n", .{ id, id, id });
            }
        }
        self.p("        default: free(cl); return;\n", .{});
        self.p("    }}\n", .{});
        self.p("}}\n\n", .{});

        for (list) |fb| {
            const id = fb.closure_id orelse continue;
            self.p("static lua_Value duo_cl_{d}(lua_Closure* cl_raw, int argc, lua_Value* argv) {{\n", .{id});
            self.indent = 1;
            self.pl("duo_closure_{d}* cl = (duo_closure_{d}*)cl_raw;", .{ id, id });
            const prev_ret = self.current_ret;
            const prev_ctx = self.closure_ctx;
            const prev_dense = self.dense_table;
            const prev_dense_cap = self.dense_table_cap;
            self.current_ret = .any;
            self.closure_ctx = fb;
            self.dense_table = null;
            self.dense_table_cap = null;
            for (fb.params, 0..) |par, i| {
                const pt = types.resolve(par.typ, null, self.alloc) catch .any;
                if (pt == .any) {
                    self.pl("lua_Value {s} = argc > {d} ? argv[{d}] : lua_val_nil();", .{ par.name, i, i });
                } else if (pt.is_integer()) {
                    self.pl("int64_t {s} = (int64_t)lua_to_num(argc > {d} ? argv[{d}] : lua_val_nil());", .{ par.name, i, i });
                } else if (pt == .f64) {
                    self.pl("double {s} = lua_to_num(argc > {d} ? argv[{d}] : lua_val_nil());", .{ par.name, i, i });
                } else if (pt == .bool) {
                    self.pl("bool {s} = lua_to_bool(argc > {d} ? argv[{d}] : lua_val_nil());", .{ par.name, i, i });
                } else if (pt == .str) {
                    self.pl("const char* {s} = lua_to_str(argc > {d} ? argv[{d}] : lua_val_nil());", .{ par.name, i, i });
                } else {
                    self.pl("lua_Value {s} = argc > {d} ? argv[{d}] : lua_val_nil();", .{ par.name, i, i });
                }
            }
            if (fb.vararg_name) |vn| {
                self.pl("lua_Value {s} = lua_tbl_pack_argv(argc - {d}, argv + {d});", .{ vn, fb.params.len, fb.params.len });
            }
            try self.emit_block(&fb.body);
            if (!self.block_fallthrough_returns(&fb.body)) {
                self.pl("return lua_val_nil();", .{});
            }
            self.indent = 0;
            self.current_ret = prev_ret;
            self.closure_ctx = prev_ctx;
            self.dense_table = prev_dense;
            self.dense_table_cap = prev_dense_cap;
            self.p("}}\n\n", .{});
        }
    }

    fn block_fallthrough_returns(self: *CodeGen, blk: *const ast.Block) bool {
        if (blk.tail_expr != null) return true;
        var i = blk.stmts.len;
        while (i > 0) {
            i -= 1;
            switch (blk.stmts[i]) {
                .ret => return true,
                .if_stmt => |*is| {
                    if (is.else_body) |*eb| {
                        if (self.block_fallthrough_returns(&is.then) and self.block_fallthrough_returns(eb))
                            return true;
                    }
                    return false;
                },
                .while_loop, .repeat_loop, .num_for, .gen_for => return false,
                else => {},
            }
        }
        return false;
    }

    fn collect_require_names(self: *CodeGen, expr: *const ast.Expr, names: *std.ArrayList([]const u8)) std.mem.Allocator.Error!void {
        switch (expr.*) {
            .call => |c| {
                if (c.func.* == .name and
                    (std.mem.eql(u8, c.func.name.ident, "require") or std.mem.eql(u8, c.func.name.ident, "req")) and
                    c.args.len == 1 and c.args[0].* == .string_lit)
                {
                    try names.append(self.alloc, c.args[0].string_lit.val);
                }
                if (self.ml_intrinsic_name(c.func) != null) {
                    return;
                }
                if (self.mem_intrinsic_name(c.func) != null) {
                    for (c.args) |a| try self.collect_require_names(a, names);
                    return;
                }
                if (self.atomic_intrinsic_name(c.func) != null) {
                    for (c.args) |a| try self.collect_require_names(a, names);
                    return;
                }
                try self.collect_require_names(c.func, names);
                for (c.args) |a| try self.collect_require_names(a, names);
            },
            .binop => |b| {
                try self.collect_require_names(b.lhs, names);
                try self.collect_require_names(b.rhs, names);
            },
            .unop => |u| try self.collect_require_names(u.operand, names),
            .method_call => |mc| {
                try self.collect_require_names(mc.obj, names);
                for (mc.args) |a| try self.collect_require_names(a, names);
            },
            .field => |f| {
                if (f.obj.* == .name and std.mem.eql(u8, f.obj.name.ident, "std")) {
                    var buf: [256]u8 = undefined;
                    const mod_name = std.fmt.bufPrint(&buf, "std.{s}", .{f.field}) catch unreachable;
                    try names.append(self.alloc, try self.alloc.dupe(u8, mod_name));
                    try names.append(self.alloc, try self.alloc.dupe(u8, "std"));
                }
                try self.collect_require_names(f.obj, names);
            },
            .index => |idx| {
                try self.collect_require_names(idx.obj, names);
                try self.collect_require_names(idx.key, names);
            },
            .table => |t| {
                for (t.fields) |fld| {
                    switch (fld) {
                        .indexed => |idx| {
                            try self.collect_require_names(idx.key, names);
                            try self.collect_require_names(idx.val, names);
                        },
                        .named => |nmd| try self.collect_require_names(nmd.val, names),
                        .positional => |pos| try self.collect_require_names(pos, names),
                    }
                }
            },
            .func_expr => |fb| try self.collect_require_names_block(&fb.body, names),
            .sequence => |seq| {
                for (seq.exprs) |e| try self.collect_require_names(e, names);
            },
            else => {},
        }
    }

    fn collect_require_names_block(self: *CodeGen, block: *const ast.Block, names: *std.ArrayList([]const u8)) std.mem.Allocator.Error!void {
        for (block.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| for (ld.inits) |e| try self.collect_require_names(e, names),
                .global_decl => |*gd| for (gd.inits) |e| try self.collect_require_names(e, names),
                .assign => |*as| for (as.values) |v| try self.collect_require_names(v, names),
                .ret => |*r| for (r.vals) |v| try self.collect_require_names(v, names),
                .if_stmt => |*is| {
                    try self.collect_require_names(is.cond, names);
                    try self.collect_require_names_block(&is.then, names);
                    for (is.elseifs) |*ei| {
                        try self.collect_require_names(ei.cond, names);
                        try self.collect_require_names_block(&ei.body, names);
                    }
                    if (is.else_body) |*eb| try self.collect_require_names_block(eb, names);
                },
                .while_loop => |*wl| {
                    try self.collect_require_names(wl.cond, names);
                    try self.collect_require_names_block(&wl.body, names);
                },
                .repeat_loop => |*rl| {
                    try self.collect_require_names_block(&rl.body, names);
                    try self.collect_require_names(rl.cond, names);
                },
                .num_for => |*nf| try self.collect_require_names_block(&nf.body, names),
                .gen_for => |*gf| {
                    for (gf.iters) |e| try self.collect_require_names(e, names);
                    try self.collect_require_names_block(&gf.body, names);
                },
                .call_stmt => |*cs| try self.collect_require_names(cs.expr, names),
                .expr_stmt => |*es| try self.collect_require_names(es.expr, names),
                .do_block => |*db| try self.collect_require_names_block(&db.body, names),
                .func_decl => |*fd| try self.collect_require_names_block(&fd.func.body, names),
                else => {},
            }
        }
    }

    fn find_module_path(self: *CodeGen, base_dir: []const u8, mod_name: []const u8) ?[]const u8 {
        const templates = .{
            "{s}/{s}.duo",
            "{s}/{s}.lua",
            "{s}/{s}/init.duo",
            "{s}/{s}/init.lua",
        };
        const cwd = Io.Dir.cwd();
        inline for (templates) |tmpl| {
            const path = std.fmt.allocPrint(self.alloc, tmpl, .{ base_dir, mod_name }) catch return null;
            if (Io.Dir.access(cwd, self.io, path, .{})) |_| {
                return path;
            } else |_| {
                self.alloc.free(path);
            }
        }
        return null;
    }

    fn emit_required_modules(self: *CodeGen, mod: *const ast.Module) E!void {
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        if (self.src_path.len > 0) {
            try self.collect_require_names_block(&mod.body, &names);
            for (mod.body.stmts) |*stmt| {
                if (stmt.* == .func_decl) {
                    try self.collect_require_names_block(&stmt.func_decl.func.body, &names);
                }
            }
        } else {
            self.p("static void duo_register_modules(void) {{\n", .{});
            self.p("}}\n\n", .{});
            return;
        }

        var seen: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen.deinit(self.alloc);
        const dir = if (self.src_path.len > 0) std.fs.path.dirname(self.src_path) orelse "." else ".";

        // Find the project root: the parent of the `src` directory that contains the source file.
        // This makes `req "src.foo"` resolve to `<project_root>/src/foo.duo` regardless of whether
        // the current source is `src/main.duo` or `src/wasm/init.duo`.
        const project_root = blk: {
            var d = dir;
            while (d.len > 0) {
                var pbuf: [1024]u8 = undefined;
                const path_to_check = std.fmt.bufPrint(&pbuf, "{s}/src", .{d}) catch break;
                const cwd = Io.Dir.cwd();
                var fd = Io.Dir.openDir(cwd, self.io, path_to_check, .{}) catch {
                    if (std.mem.eql(u8, d, ".")) break;
                    d = std.fs.path.dirname(d) orelse ".";
                    continue;
                };
                fd.close(self.io);
                break :blk d;
            }
            break :blk dir;
        };

        var embedded: std.ArrayList(struct { name: []const u8, cname: []const u8 }) = .empty;
        defer {
            for (embedded.items) |e| self.alloc.free(e.cname);
            embedded.deinit(self.alloc);
        }

        // If the source references the root `std` namespace (via `require "std"`
        // or a bare `std` value), build a lightweight runtime table that re-exports
        // only the std submodules that were actually requested.  This keeps std
        // inclusion lazy: unused std submodules are not parsed, typed, or emitted.
        const needs_std_root = blk: {
            for (names.items) |n| {
                if (std.mem.eql(u8, n, "std")) break :blk true;
            }
            break :blk false;
        };

        var i: usize = 0;
        while (i < names.items.len) : (i += 1) {
            const name = names.items[i];
            if (seen.contains(name)) continue;
            try seen.put(self.alloc, name, {});
            if (self.src_path.len == 0) continue;
            if (std.mem.eql(u8, name, "std")) continue;

            // Handle collection-style namespaces: vendor.xxx → vendor/xxx, std.core.xxx → lib/core/xxx
            const vendor_prefix = "vendor.";
            const core_prefix = "std.core.";
            const has_vendor = std.mem.startsWith(u8, name, vendor_prefix);
            const has_core = std.mem.startsWith(u8, name, core_prefix);
            const strip_len: usize = if (has_vendor) vendor_prefix.len else if (has_core) core_prefix.len else 0;
            const mod_path_name = if (strip_len > 0) blk: {
                const s = try self.alloc.dupe(u8, name[strip_len..]);
                for (s) |*c| {
                    if (c.* == '.') c.* = '/';
                }
                break :blk s;
            } else blk: {
                const s = try self.alloc.dupe(u8, name);
                for (s) |*c| {
                    if (c.* == '.') c.* = '/';
                }
                break :blk s;
            };
            defer self.alloc.free(mod_path_name);

            var mod_path: ?[]const u8 = null;
            if (self.find_module_path(project_root, mod_path_name)) |path| {
                mod_path = path;
            } else if (self.stdlib_root) |root| {
                mod_path = self.find_module_path(root, mod_path_name);
            }
            if (mod_path == null) {
                mod_path = self.find_module_path("lib", mod_path_name);
            }
            if (mod_path == null and has_vendor) {
                mod_path = self.find_module_path("vendor", mod_path_name);
            }
            if (mod_path == null and has_core) {
                mod_path = self.find_module_path("lib/core", mod_path_name);
            }

            if (mod_path == null) continue;
            defer self.alloc.free(mod_path.?);
            const cname = try self.module_c_name(name);
            if (!self.emit_embedded_module(cname, mod_path.?)) {
                term.warn("failed to embed module '{s}' from {s}", .{ name, mod_path.? });
                continue;
            }
            try embedded.append(self.alloc, .{ .name = name, .cname = cname });
            // Recursively collect nested require names from the embedded module
            {
                const sub_src = Io.Dir.readFileAlloc(Io.Dir.cwd(), self.io, mod_path.?, self.alloc, .unlimited) catch |e| {
                    term.err("emit_required_modules: re-read failed for {s}: {}", .{ mod_path.?, e });
                    continue;
                };
                defer self.alloc.free(sub_src);
                var sub_lex = @import("lexer.zig").Lexer.init(sub_src, mod_path.?);
                var sub_parser = @import("parser.zig").Parser.init(&sub_lex, self.alloc);
                var sub_mod = sub_parser.parse_module() catch |e| {
                    term.err("emit_required_modules: re-parse failed for {s}: {}", .{ mod_path.?, e });
                    continue;
                };
                try self.collect_require_names_block(&sub_mod.body, &names);
                for (sub_mod.body.stmts) |*sub_stmt| {
                    if (sub_stmt.* == .func_decl) {
                        try self.collect_require_names_block(&sub_stmt.func_decl.func.body, &names);
                    }
                }
            }
        }

        var std_root_count: usize = 0;
        for (embedded.items) |e| {
            if (std.mem.startsWith(u8, e.name, "std.")) std_root_count += 1;
        }

        // Forward-declare duo_build_std_root if needed (defined after duo_register_modules)
        if (needs_std_root) {
            self.p("static lua_Value duo_build_std_root(lua_Value _unused);\n", .{});
        }
        self.p("static void duo_register_modules(void) {{\n", .{});
        for (embedded.items) |e| {
            self.p("    lua_table_set_raw_lit(duo_modules, \"", .{});
            try self.emit_string_escaped(e.name);
            self.p("\", {d}, {d}, lua_val_from_func((lua_Value (*)(lua_Value))duo_mod_{s}));\n", .{ calc_lua_hash(e.name), e.name.len, e.cname });
        }
        if (needs_std_root) {
            self.p("    lua_table_set_raw_lit(duo_modules, \"std\", {d}, 3, lua_val_from_func((lua_Value (*)(lua_Value))duo_build_std_root));\n", .{calc_lua_hash("std")});
        }
        self.p("}}\n\n", .{});

        if (needs_std_root) {
            self.p("static lua_Value duo_build_std_root(lua_Value _unused) {{\n", .{});
            self.p("    (void)_unused;\n", .{});
            self.p("    lua_Value root = lua_table_new_with_capacity(0, {d});\n", .{std_root_count});
            for (embedded.items) |e| {
                if (std.mem.startsWith(u8, e.name, "std.")) {
                    const sub = e.name[4..];
                    self.p("    lua_table_set_raw_lit(root, \"", .{});
                    try self.emit_string_escaped(sub);
                    self.p("\", {d}, {d}, lua_require(lua_val_lit(\"", .{ calc_lua_hash(sub), sub.len });
                    try self.emit_string_escaped(e.name);
                    self.p("\")));\n", .{});
                }
            }
            self.p("    return root;\n", .{});
            self.p("}}\n\n", .{});
        }
    }

    fn module_c_name(self: *CodeGen, name: []const u8) std.mem.Allocator.Error![]u8 {
        var out: std.ArrayList(u8) = .empty;
        defer out.deinit(self.alloc);
        for (name) |c| {
            if (std.ascii.isAlphanumeric(c) or c == '_')
                try out.append(self.alloc, c)
            else
                try out.append(self.alloc, '_');
        }
        return out.toOwnedSlice(self.alloc);
    }

    fn add_module_export(
        self: *CodeGen,
        seen: *std.StringArrayHashMapUnmanaged(void),
        names: *std.ArrayList([]const u8),
        name: []const u8,
    ) E!void {
        if (name.len == 0 or name[0] == '_') return;
        if (seen.contains(name)) return;
        try seen.put(self.alloc, name, {});
        try names.append(self.alloc, name);
    }

    fn collect_duo_module_exports(self: *CodeGen, mod: *const ast.Module, names: *std.ArrayList([]const u8)) E!void {
        var seen: std.StringArrayHashMapUnmanaged(void) = .{};
        defer seen.deinit(self.alloc);

        for (mod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .local_decl => |*ld| {
                    for (ld.names) |*lname| try self.add_module_export(&seen, names, lname.ident);
                },
                .global_decl => |*gd| {
                    if (!gd.star) for (gd.names) |*lname| try self.add_module_export(&seen, names, lname.ident);
                },
                .const_decl => |*cd| try self.add_module_export(&seen, names, cd.ident),
                .assign => |*as| {
                    for (as.targets) |target| {
                        if (target.* == .name) try self.add_module_export(&seen, names, target.name.ident);
                    }
                },
                .func_decl => |*fd| {
                    if (fd.path.len == 1 and !fd.method) try self.add_module_export(&seen, names, fd.path[0]);
                },
                else => {},
            }
        }
    }

    fn find_duo_module_func(mod: *const ast.Module, name: []const u8) ?*const ast.FuncDecl {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .func_decl) continue;
            const fd = &stmt.func_decl;
            if (fd.method or fd.path.len != 1) continue;
            if (std.mem.eql(u8, fd.path[0], name)) return fd;
        }
        return null;
    }

    fn find_duo_module_const(mod: *const ast.Module, name: []const u8) ?*const ast.Expr {
        for (mod.body.stmts) |*stmt| {
            if (stmt.* != .const_decl) continue;
            const cd = &stmt.const_decl;
            if (std.mem.eql(u8, cd.ident, name)) return cd.val;
        }
        return null;
    }

    fn emit_duo_module_return_table(self: *CodeGen, mod: *const ast.Module) E!void {
        var names: std.ArrayList([]const u8) = .empty;
        defer names.deinit(self.alloc);
        try self.collect_duo_module_exports(mod, &names);

        self.ind();
        self.p("lua_Value __duo_module = lua_table_new_with_capacity(0, {d});\n", .{names.items.len});
        for (names.items) |name| {
            const hash = calc_lua_hash(name);
            var name_expr = ast.Expr{ .name = .{ .loc = mod.body.loc, .ident = name } };
            self.ind();
            self.p("lua_table_set_raw_lit(__duo_module, \"", .{});
            try self.emit_string_escaped(name);
            self.p("\", {d}, {d}, ", .{ hash, name.len });
            if (find_duo_module_func(mod, name)) |fd| {
                const ft = self.func_expr_type(&fd.func);
                if (ft == .func) {
                    try self.emit_native_func_name_as_lua_value(name, ft.func.params, ft.func.is_native);
                } else {
                    try self.emit_as_lua_value(&name_expr);
                }
            } else if (find_duo_module_const(mod, name)) |cval| {
                try self.emit_as_lua_value(cval);
            } else if (self.module_globals) |globals| {
                if (globals.get(name)) |gt| {
                    if (gt == .func) {
                        try self.emit_native_func_name_as_lua_value(name, gt.func.params, gt.func.is_native);
                    } else {
                        try self.emit_as_lua_value(&name_expr);
                    }
                } else {
                    try self.emit_as_lua_value(&name_expr);
                }
            } else {
                try self.emit_as_lua_value(&name_expr);
            }
            self.p(");\n", .{});
        }
        self.ind();
        self.p("return __duo_module;\n", .{});
    }

    fn emit_embedded_module(self: *CodeGen, cname: []const u8, path: []const u8) bool {
        const cwd = Io.Dir.cwd();
        const src = Io.Dir.readFileAlloc(cwd, self.io, path, self.alloc, .unlimited) catch |e| {
            term.err("emit_embedded_module: readFileAlloc failed for {s}: {}", .{ path, e });
            return false;
        };
        // The parser stores identifier/string slices into this buffer. Embedded
        // closure bodies are emitted after this function returns, so the source
        // must live for the duration of code generation.

        var lex = @import("lexer.zig").Lexer.init(src, path);
        var parser = @import("parser.zig").Parser.init(&lex, self.alloc);
        var submod = parser.parse_module() catch |e| {
            term.err("emit_embedded_module: parse failed for {s}: {}", .{ path, e });
            return false;
        };
        var subsem = sema.Sema.init(self.alloc);
        defer subsem.deinit();
        subsem.lua55_mode = std.mem.endsWith(u8, path, ".lua");
        subsem.duo_mode = std.mem.endsWith(u8, path, ".duo");
        subsem.next_closure_id = self.next_closure_id;
        subsem.check_module(&submod) catch |e| {
            term.err("emit_embedded_module: sema failed for {s}: {}", .{ path, e });
            return false;
        };
        self.next_closure_id = subsem.next_closure_id;
        const old_duo_mode = self.duo_mode;
        const old_module_globals = self.module_globals;
        const old_module_cname = self.current_module_cname;
        self.duo_mode = subsem.duo_mode;
        self.module_globals = &subsem.module_globals;
        self.current_module_cname = cname;
        defer {
            self.duo_mode = old_duo_mode;
            self.module_globals = old_module_globals;
            self.current_module_cname = old_module_cname;
        }
        // Copy submodule type map into main type map so codegen can resolve types
        // for submodule expressions.
        var type_it = subsem.type_map.iterator();
        while (type_it.next()) |entry| {
            self.type_map.put(entry.key_ptr.*, entry.value_ptr.*) catch |e| {
                term.err("emit_embedded_module: type map merge failed: {}", .{e});
                return false;
            };
        }

        // Promote module-level mutable globals to static file-scope storage.
        // Functions are emitted at file scope, so they cannot see locals that were
        // declared inside the module-init function.  Static storage makes the
        // shared module state visible to every function in the module.
        if (self.module_globals) |globals| {
            var globals_it = globals.iterator();
            var any_global = false;
            while (globals_it.next()) |entry| {
                any_global = true;
                const rt = entry.value_ptr.*;
                if (rt == .any) {
                    self.p("static lua_Value duo_g_{s}_{s};\n", .{ self.current_module_cname, entry.key_ptr.* });
                } else {
                    var buf: [128]u8 = undefined;
                    self.p("static {s} duo_g_{s}_{s};\n", .{ rt.c_type(&buf), self.current_module_cname, entry.key_ptr.* });
                }
            }
            if (any_global) self.p("\n", .{});
        }

        // Emit submodule closure structs
        const start_idx = self.all_closures.items.len;
        self.collect_closures_module(&submod, &self.all_closures) catch {};
        self.emit_closure_structs(self.all_closures.items[start_idx..]) catch {};

        // Emit submodule constants at file scope. Table-valued constants are
        // declared here; their init functions are emitted after submodule
        // function definitions so the init functions can call module functions.
        var table_consts: std.ArrayList(*const ast.Stmt) = .empty;
        defer table_consts.deinit(self.alloc);
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .const_decl) {
                const cd = &stmt.const_decl;
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(cd.ident, &name_buf);
                const rt = if (cd.typ != .inferred)
                    types.resolve(cd.typ, null, self.alloc) catch .any
                else
                    self.expr_type(cd.val);
                if (cd.val.* == .table) {
                    // Table literal: forward-declare static storage; _init emitted later
                    self.p("static lua_Value {s};\n", .{mname});
                    table_consts.append(self.alloc, stmt) catch |e| {
                        term.err("emit_embedded_module: oom collecting table const {s}: {}", .{ cd.ident, e });
                        return false;
                    };
                } else {
                    self.p("static const ", .{});
                    self.typ(rt);
                    self.p(" {s} = ", .{mname});
                    self.emit_expr(cd.val) catch |e| {
                        term.err("emit_embedded_module: expr emit failed for const {s}: {}", .{ cd.ident, e });
                        return false;
                    };
                    self.p(";\n", .{});
                }
                self.note_comptime_binding(cd.ident, cd.val) catch |e| {
                    term.err("emit_embedded_module: comptime binding failed for const {s}: {}", .{ cd.ident, e });
                    return false;
                };
            }
        }

        // Emit module-level @c.emit directives at file scope so raw C
        // declarations (e.g., struct/typedef definitions) are visible to
        // file-scope functions in the submodule.
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .directive and std.mem.eql(u8, stmt.directive.attr.name, "c.emit")) {
                const code = @import("directives.zig").extractCRawCode(stmt.directive.attr.args orelse "");
                const trimmed = std.mem.trim(u8, code, " \t\r\n");
                if (trimmed.len > 0 and trimmed[trimmed.len - 1] != ';' and trimmed[trimmed.len - 1] != '}')
                    self.p("{s};\n", .{code})
                else
                    self.p("{s}\n", .{code});
            }
        }
        self.nl();

        // Collect all top-level and nested local functions from submodule
        var sub_funcs: std.ArrayList(*ast.FuncDecl) = .empty;
        defer sub_funcs.deinit(self.alloc);
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .func_decl) {
                sub_funcs.append(self.alloc, &stmt.func_decl) catch |e| {
                    term.err("emit_embedded_module: oom collecting funcs: {}", .{e});
                    return false;
                };
            }
        }
        var nested: std.ArrayList(*ast.FuncDecl) = .empty;
        defer nested.deinit(self.alloc);
        for (sub_funcs.items) |fd| {
            self.collect_local_funcs_block(&fd.func.body, &nested) catch |e| {
                term.err("emit_embedded_module: oom collecting nested funcs: {}", .{e});
                return false;
            };
        }
        sub_funcs.appendSlice(self.alloc, nested.items) catch |e| {
            term.err("emit_embedded_module: oom appending nested funcs: {}", .{e});
            return false;
        };

        // Forward-declare submodule functions
        for (sub_funcs.items) |fd| {
            if (fd.path.len == 1 and !fd.method) {
                self.note_func_body(fd.path[0], &fd.func) catch |e| {
                    term.err("emit_embedded_module: func body registration failed for {s}: {}", .{ fd.path[0], e });
                    return false;
                };
                self.emit_func_decl_forward(fd) catch |e| {
                    term.err("emit_embedded_module: forward decl failed for {s}: {}", .{ fd.path[0], e });
                    return false;
                };
            }
        }
        // Emit submodule function definitions at file scope
        for (sub_funcs.items) |fd| {
            self.emit_func_def(fd) catch |e| {
                term.err("emit_embedded_module: func def failed for {s}: {}", .{ fd.path[0], e });
                return false;
            };
        }

        // Emit table-valued submodule const init functions after function definitions
        // so they can call module functions that are already declared.
        for (table_consts.items) |stmt| {
            const cd = &stmt.const_decl;
            var name_buf: [256]u8 = undefined;
            const mname = self.mangled_name(cd.ident, &name_buf);
            self.p("static void _init_{s}(void) {{\n", .{mname});
            self.indent += 1;
            self.ind();
            self.p("{s} = ", .{mname});
            self.emit_expr(cd.val) catch |e| {
                term.err("emit_embedded_module: _init expr emit failed for const {s}: {}", .{ cd.ident, e });
                return false;
            };
            self.p(";\n", .{});
            self.indent -= 1;
            self.ind();
            self.p("}}\n", .{});
        }
        if (table_consts.items.len > 0) self.p("\n", .{});

        self.p("static lua_Value duo_mod_{s}(lua_Value _unused) {{\n", .{cname});
        self.p("    (void)_unused;\n", .{});
        self.indent = 1;
        const prev_ret = self.current_ret;
        const prev_ctx = self.closure_ctx;
        self.current_ret = .any;
        self.closure_ctx = null;
        self.push_local_scope() catch |e| {
            term.err("emit_embedded_module: scope setup failed: {}", .{e});
            return false;
        };
        // Initialize table-valued submodule constants
        for (submod.body.stmts) |*stmt| {
            if (stmt.* == .const_decl and stmt.const_decl.val.* == .table) {
                self.ind();
                var name_buf: [256]u8 = undefined;
                const mname = self.mangled_name(stmt.const_decl.ident, &name_buf);
                self.p("_init_{s}();\n", .{mname});
            }
        }
        for (submod.body.stmts) |*stmt| {
            switch (stmt.*) {
                .func_decl, .const_decl => {},
                .directive => |dir| {
                    if (std.mem.eql(u8, dir.attr.name, "c.emit")) continue;
                    self.emit_stmt(stmt) catch |e| {
                        term.err("emit_embedded_module: stmt emit failed: {}", .{e});
                        return false;
                    };
                },
                else => self.emit_stmt(stmt) catch |e| {
                    term.err("emit_embedded_module: stmt emit failed: {}", .{e});
                    return false;
                },
            }
        }
        if (submod.body.tail_expr) |expr| {
            self.ind();
            self.p("return ", .{});
            self.emit_as_lua_value(expr) catch |e| {
                term.err("emit_embedded_module: tail expr emit failed: {}", .{e});
                return false;
            };
            self.p(";\n", .{});
        } else if (subsem.duo_mode) {
            self.emit_duo_module_return_table(&submod) catch |e| {
                term.err("emit_embedded_module: auto module table emit failed: {}", .{e});
                return false;
            };
        } else {
            self.pl("return lua_val_nil();", .{});
        }
        self.pop_local_scope();
        self.indent = 0;
        self.current_ret = prev_ret;
        self.closure_ctx = prev_ctx;
        self.p("}}\n\n", .{});
        return true;
    }

    // ── Duo Language Extensions ────────────────────────────────────────────────

    /// Emit a match expression or statement as nested if/switch in C.
    fn emit_match_expr(self: *CodeGen, match_expr: anytype) E!void {
        // Generate a temporary variable to hold the scrutinee value
        const scrutinee_var = try self.alloc.dupe(u8, "__match_s");
        defer self.alloc.free(scrutinee_var);

        // Emit scrutinee evaluation. Use the scrutinee's concrete C type
        // rather than the GNU `auto` extension so the code is portable.
        const scrutinee_type = self.expr_type(match_expr.scrutinee);
        self.p("({{", .{});
        self.indent += 1;
        self.ind();
        self.typ(scrutinee_type);
        self.p(" __match_s = ", .{});
        try self.emit_expr(match_expr.scrutinee);
        self.p(";", .{});

        // Generate arms
        for (match_expr.arms, 0..) |arm, i| {
            self.nl();
            self.ind();

            if (i == 0) {
                self.p("if (", .{});
            } else {
                self.p("else if (", .{});
            }

            try self.emit_pattern_condition(arm.pattern, scrutinee_var, scrutinee_type);
            self.p(") {{", .{});

            self.indent += 1;
            self.nl();

            try self.emit_pattern_bindings(arm.pattern, scrutinee_var, scrutinee_type);

            // Emit guard if present
            if (arm.guard) |guard| {
                self.ind();
                self.p("if (!(", .{});
                try self.emit_expr(guard);
                self.p(")) goto __match_arm_{d}_fail;", .{i});
                self.nl();
            }

            // Emit arm body (Block contains stmts)
            for (arm.body.stmts) |*stmt| {
                try self.emit_stmt(stmt);
            }

            if (arm.guard != null) {
                self.nl();
                self.indent -= 1;
                self.ind();
                self.p("__match_arm_{d}_fail:;", .{i});
                self.indent += 1;
            }

            self.indent -= 1;
            self.nl();
            self.ind();
            self.p("}}", .{});
        }

        // Default case if no wildcard
        self.nl();
        self.ind();
        self.p("else {{", .{});
        self.indent += 1;
        self.nl();
        self.ind();
        self.p("lua_error(lua_val_from_str(\"match non-exhaustive\"));", .{});
        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}}", .{});

        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}})", .{});
    }

    /// Emit pattern matching condition for an arm. `scrutinee_type` is the
    /// resolved type of the value being matched, used to pick the enum
    /// representation for variant patterns.
    fn emit_pattern_condition(self: *CodeGen, pattern: ast.Pattern, scrutinee_var: []const u8, scrutinee_type: RT) E!void {
        switch (pattern) {
            .wildcard => self.p("1", .{}), // Always match
            .literal => |lit| {
                self.p("(", .{});
                if (scrutinee_type == .any) {
                    const lit_t = self.expr_type(lit);
                    if (lit_t.is_numeric()) {
                        self.p("lua_to_num({s}) == ", .{scrutinee_var});
                        try self.emit_expr(lit);
                    } else if (lit_t == .bool) {
                        self.p("lua_to_bool({s}) == ", .{scrutinee_var});
                        try self.emit_expr(lit);
                    } else if (lit_t == .str) {
                        self.p("strcmp(lua_to_str({s}), ", .{scrutinee_var});
                        try self.emit_expr(lit);
                        self.p(") == 0", .{});
                    } else {
                        self.p("{s} == ", .{scrutinee_var});
                        try self.emit_expr(lit);
                    }
                } else {
                    self.p("{s} == ", .{scrutinee_var});
                    try self.emit_expr(lit);
                }
                self.p(")", .{});
            },
            .binding => |b| {
                _ = b;
                self.p("1", .{});
            },
            .variant => |v| {
                // The pattern tag may be qualified ("Color.Red") or bare
                // ("Red"). Resolve the enum name from the scrutinee type and
                // the variant name from the tail of the tag.
                const variant_name = if (std.mem.lastIndexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[dot + 1 ..]
                else
                    v.tag;
                const enum_name = if (scrutinee_type == .enum_type)
                    scrutinee_type.enum_type.name
                else if (std.mem.indexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[0..dot]
                else
                    v.tag;
                const has_payload = self.enum_has_payload.get(enum_name) orelse false;
                self.p("(", .{});
                if (has_payload) {
                    self.p("{s}.tag == duo_{s}_tag_{s}", .{ scrutinee_var, enum_name, variant_name });
                } else {
                    self.p("{s} == duo_{s}_{s}", .{ scrutinee_var, enum_name, variant_name });
                }
                // Recursively check non-trivial sub-pattern conditions for payload fields.
                if (has_payload) {
                    if (v.payload) |payload_pats| {
                        if (self.find_enum_variant_def(enum_name, variant_name)) |vdef| {
                            const fields = vdef.payload orelse &.{};
                            for (payload_pats, 0..) |sub_pat, fi| {
                                switch (sub_pat) {
                                    .wildcard, .binding => continue,
                                    else => {},
                                }
                                const field_name = if (fi < fields.len)
                                    fields[fi].name orelse (try std.fmt.allocPrint(self.alloc, "_{d}", .{fi}))
                                else
                                    try std.fmt.allocPrint(self.alloc, "_{d}", .{fi});
                                const owns_field = fi >= fields.len or fields[fi].name == null;
                                defer if (owns_field) self.alloc.free(field_name);
                                const payload_expr = try std.fmt.allocPrint(self.alloc, "{s}.as.{s}.{s}", .{
                                    scrutinee_var, variant_name, field_name,
                                });
                                defer self.alloc.free(payload_expr);
                                const ft = if (fi < fields.len)
                                    types.resolve(fields[fi].typ, null, self.alloc) catch RT.any
                                else
                                    RT.any;
                                self.p(" && ", .{});
                                try self.emit_pattern_condition(sub_pat, payload_expr, ft);
                            }
                        }
                    }
                }
                self.p(")", .{});
            },
            else => self.p("1", .{}), // Conservative: match everything
        }
    }

    fn emit_pattern_bindings(self: *CodeGen, pattern: ast.Pattern, scrutinee_var: []const u8, scrutinee_type: RT) E!void {
        try self.emit_pattern_binding_from(pattern, scrutinee_var, scrutinee_type);
    }

    fn emit_pattern_binding_from(self: *CodeGen, pattern: ast.Pattern, value_expr: []const u8, value_type: RT) E!void {
        switch (pattern) {
            .binding => |b| {
                const bind_type = if (b.typ) |type_expr|
                    types.resolve(type_expr, null, self.alloc) catch value_type
                else
                    value_type;
                self.ind();
                self.typ(bind_type);
                self.p(" {s} = {s};\n", .{ b.name, value_expr });
                try self.note_local_type(b.name, bind_type);
            },
            .variant => |v| {
                const variant_name = if (std.mem.lastIndexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[dot + 1 ..]
                else
                    v.tag;
                const enum_name = if (value_type == .enum_type)
                    value_type.enum_type.name
                else if (std.mem.indexOfScalar(u8, v.tag, '.')) |dot|
                    v.tag[0..dot]
                else
                    v.tag;
                const variant = self.find_enum_variant_def(enum_name, variant_name) orelse return;
                const fields = variant.payload orelse return;
                const payload_pats = v.payload orelse return;
                for (payload_pats, 0..) |sub_pat, i| {
                    if (i >= fields.len) break;
                    const field_type = types.resolve(fields[i].typ, null, self.alloc) catch RT.any;
                    const field_name = fields[i].name orelse try std.fmt.allocPrint(self.alloc, "_{d}", .{i});
                    defer if (fields[i].name == null) self.alloc.free(field_name);
                    const payload_expr = try std.fmt.allocPrint(self.alloc, "{s}.as.{s}.{s}", .{ value_expr, variant_name, field_name });
                    defer self.alloc.free(payload_expr);
                    try self.emit_pattern_binding_from(sub_pat, payload_expr, field_type);
                }
            },
            .table_destr => |entries| {
                for (entries) |entry| {
                    const key_hash = calc_lua_hash(entry.key);
                    const field_expr = try std.fmt.allocPrint(self.alloc, "lua_table_get_str_lit({s}, \"{s}\", {d}u, {d})", .{ value_expr, entry.key, key_hash, entry.key.len });
                    defer self.alloc.free(field_expr);
                    try self.emit_pattern_binding_from(entry.pat, field_expr, .any);
                }
            },
            .array_destr => |pats| {
                for (pats, 0..) |sub_pat, ai| {
                    const elem_expr = try std.fmt.allocPrint(self.alloc, "lua_table_get_num({s}, {d})", .{ value_expr, ai + 1 });
                    defer self.alloc.free(elem_expr);
                    try self.emit_pattern_binding_from(sub_pat, elem_expr, .any);
                }
            },
            .rest => |name| {
                self.ind();
                self.p("lua_Value {s} = {s};\n", .{ name, value_expr });
                try self.note_local_type(name, .any);
            },
            else => {},
        }
    }

    /// Emit a try/catch statement.
    fn emit_try_stmt(self: *CodeGen, try_stmt: ast.TryStmt) E!void {
        // Use setjmp/longjmp for error handling
        self.p("({{", .{});
        self.indent += 1;
        self.nl();
        self.ind();
        self.p("jmp_buf __try_env;", .{});
        self.nl();
        self.ind();
        self.p("if (setjmp(__try_env) == 0) {{", .{});

        // Try block
        self.indent += 1;
        self.nl();
        for (try_stmt.body.stmts) |*stmt| {
            try self.emit_stmt(stmt);
        }
        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}}", .{});

        // Catch clauses
        for (try_stmt.catches) |catch_clause| {
            self.p(" else {{", .{});
            self.indent += 1;
            self.nl();

            if (catch_clause.binding) |var_name| {
                self.ind();
                self.p("lua_Value {s} = __catch_val;", .{var_name});
                self.nl();
            }

            for (catch_clause.body.stmts) |*stmt| {
                try self.emit_stmt(stmt);
            }

            self.indent -= 1;
            self.nl();
            self.ind();
            self.p("}}", .{});
        }

        self.indent -= 1;
        self.nl();
        self.ind();
        self.p("}})", .{});
    }
};

